45: // Startup is called by Wails when the runtime is ready.
46: func (a *App) Startup(ctx context.Context) {
47: 	a.ctx = ctx
48: 	_, a.cancel = context.WithCancel(ctx)
49: 
50: 	// 1. Initialize configuration store
51: 	var cfgErr error
52: 	a.cfg, cfgErr = config.NewStore()
53: 	if cfgErr != nil {
54: 		panic(fmt.Sprintf("failed to initialize config store: %v", cfgErr))
55: 	}
56: 
57: 	// 2. Initialize file and event logger
58: 	home, _ := os.UserHomeDir()
59: 	logDir := filepath.Join(home, ".gitsync", "logs")
60: 	prefs := a.cfg.Config().Preferences
61: 	a.log = logger.New(logger.Prefs{
62: 		LogMaxSizeMB: prefs.LogMaxSizeMB,
63: 		LogMaxFiles:  prefs.LogMaxFiles,
64: 	}, logDir, a.emitEvent)
65: 
66: 	a.log.Info("app", "GitSync starting up")
67: 
68: 	// 3. Clean up stale .git/index.lock files from previous crashes or ungraceful kills
69: 	a.cleanupStaleIndexLocks()
70: 
71: 	// 4. Initialize Git engine with portable/custom Git support
72: 	a.git = gitengine.New(a.log, prefs.GitPath)
73: 	if !a.git.Available() {
74: 		a.log.Warn("app", "Git binary not found — please ensure Git is installed or configure a custom path")
75: 	}
76: 
77: 	// 5. Initialize GitHub multi-account client pool
78: 	a.github = githubapi.NewPool(a.cfg, a.log)
79: 
80: 	// 6. Initialize and start the background watcher service
81: 	a.watchSvc = watcher.New(a.cfg, a.git, a.github, a.log, a.emitEvent)
82: 	a.watchSvc.Start(a.ctx)
83: 
84: 	// 7. Start system tray integration in a background goroutine
85: 	go tray.Run(a.ctx, a.cfg, a.log, a.showWindow, a.hideWindow, a.quitApp)
86: 
87: 	// 8. Start periodic tray metrics sync ticker
88: 	go a.startTrayMetricsLoop()
89: 
90: 	// 9. Start background 24-hour auto-updater
91: 	a.updater = updater.New(a.log, a.emitEvent)
92: 	a.updater.Start(a.ctx)
93: 
94: 	a.log.Info("app", "GitSync initialized successfully")
95: }
