130: // shutdown is called during application termination.
131: func (a *App) shutdown(ctx context.Context) {
132: 	a.log.Info("app", "GitSync shutting down...")
133: 	if a.cancel != nil {
134: 		a.cancel()
135: 	}
136: 
137: 	// Allow in-flight git sync operations up to 8 seconds to cleanly drain
138: 	shutdownCtx, cancel := context.WithTimeout(context.Background(), 8*time.Second)
139: 	defer cancel()
140: 	if a.watchSvc != nil {
141: 		a.watchSvc.Stop(shutdownCtx)
142: 	}
143: 
144: 	if a.log != nil {
145: 		a.log.Flush()
146: 		a.log.Close()
147: 	}
148: 	if a.cfg != nil {
149: 		_ = a.cfg.Save()
150: 	}
151: }
