203: // emitEvent dispatches a typed event and payload to the Wails frontend.
204: func (a *App) emitEvent(name string, data interface{}) {
205: 	if a.ctx != nil {
206: 		wailsRuntime.EventsEmit(a.ctx, name, data)
207: 	}
208: 	if name == "repo:status" || name == "global_pause:changed" || name == "config:updated" {
209: 		tray.UpdateMetrics(a.calculateTrayMetrics())
210: 	}
211: }
