213: func (a *App) calculateTrayMetrics() tray.Metrics {
214: 	if a.cfg == nil || a.watchSvc == nil {
215: 		return tray.Metrics{}
216: 	}
217: 	cfg := a.cfg.Config()
218: 	statuses := a.watchSvc.Statuses()
219: 
220: 	m := tray.Metrics{
221: 		TotalRepos: len(cfg.Repos),
222: 		IsPaused:   cfg.Preferences.GlobalPause,
223: 	}
224: 
225: 	for _, r := range cfg.Repos {
226: 		if r.Enabled {
227: 			m.ActiveRepos++
228: 		}
229: 	}
230: 
231: 	for _, st := range statuses {
232: 		if st.State == "syncing" {
233: 			m.Syncing++
234: 		}
235: 		if st.State == "conflict" {
236: 			m.Conflicts++
237: 		}
238: 		if st.PendingFiles > 0 || st.State == "debouncing" {
239: 			m.PendingSyncs += st.PendingFiles
240: 			if st.PendingFiles == 0 {
241: 				m.PendingSyncs++
242: 			}
243: 		}
244: 	}
245: 
246: 	return m
247: }
