249: func (a *App) startTrayMetricsLoop() {
250: 	ticker := time.NewTicker(4 * time.Second)
251: 	defer ticker.Stop()
252: 
253: 	for {
254: 		select {
255: 		case <-a.ctx.Done():
256: 			return
257: 		case <-ticker.C:
258: 			tray.UpdateMetrics(a.calculateTrayMetrics())
259: 		}
260: 	}
261: }
