303: // ValidateAndSaveGitHubAccount verifies the PAT against GitHub's /user API,
304: // extracts username and avatar, encrypts it via the AES-256-GCM vault, and saves it to config.
305: func (a *App) ValidateAndSaveGitHubAccount(tokenName string, patToken string) (config.Account, error) {
306: 	patToken = strings.TrimSpace(patToken)
307: 	if patToken == "" {
308: 		return config.Account{}, fmt.Errorf("personal access token cannot be empty")
309: 	}
310: 
311: 	ctx, cancel := context.WithTimeout(context.Background(), 12*time.Second)
312: 	defer cancel()
313: 
314: 	userInfo, rateInfo, err := a.github.VerifyToken(ctx, patToken)
315: 	if err != nil {
316: 		if a.log != nil {
317: 			a.log.Warn("auth", "GitHub PAT validation failed: %v", err)
318: 		}
319: 		return config.Account{}, fmt.Errorf("GitHub authentication failed: %w", err)
320: 	}
321: 
322: 	return a.saveValidatedAccount(tokenName, patToken, userInfo, rateInfo)
323: }
