331: // StartGitHubOAuth starts the local loopback OAuth server on port 8080 (http://127.0.0.1:8080/auth/callback),
332: // opens the user's default browser to GitHub's authorization consent page, exchanges the code with the OAuth App Client Secret,
333: // and saves the account.
334: func (a *App) StartGitHubOAuth() (config.Account, error) {
335: 	if a.github == nil || a.github.OAuth() == nil {
336: 		return config.Account{}, fmt.Errorf("OAuth service not initialized")
337: 	}
338: 
339: 	oauth := a.github.OAuth()
340: 	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Minute)
341: 	defer cancel()
342: 
343: 	authURL, resChan, err := oauth.StartOAuthServer(ctx)
344: 	if err != nil {
345: 		if a.log != nil {
346: 			a.log.Warn("oauth", "Failed to start OAuth server: %v", err)
347: 		}
348: 		return config.Account{}, fmt.Errorf("failed to start OAuth listener: %w", err)
349: 	}
350: 
351: 	if a.log != nil {
352: 		a.log.Info("oauth", "Started OAuth flow, launching system browser to %s", authURL)
353: 	}
354: 
355: 	// Launch default system browser
356: 	if a.ctx != nil {
357: 		wailsRuntime.BrowserOpenURL(a.ctx, authURL)
358: 	}
359: 
360: 	// Await callback or timeout
361: 	select {
362: 	case res := <-resChan:
363: 		if res.Error != nil {
364: 			if a.log != nil {
365: 				a.log.Warn("oauth", "OAuth flow error: %v", res.Error)
366: 			}
367: 			return config.Account{}, res.Error
368: 		}
369: 
370: 		// Verify obtained token & fetch user profile
371: 		verifyCtx, vCancel := context.WithTimeout(context.Background(), 15*time.Second)
372: 		defer vCancel()
373: 
374: 		userInfo, rateInfo, err := a.github.VerifyToken(verifyCtx, res.Token)
375: 		if err != nil {
376: 			return config.Account{}, fmt.Errorf("verify OAuth token: %w", err)
377: 		}
378: 
379: 		label := ""
380: 		if userInfo.Name != "" {
381: 			label = userInfo.Name
382: 		} else {
383: 			label = fmt.Sprintf("@%s", userInfo.Username)
384: 		}
385: 
386: 		account, err := a.saveValidatedAccount(label, res.Token, userInfo, rateInfo)
387: 		if err != nil {
388: 			return config.Account{}, err
389: 		}
390: 
391: 		if a.log != nil {
392: 			a.log.Info("oauth", "Successfully linked GitHub account via OAuth: @%s (%s)", account.Username, account.Label)
393: 		}
394: 		return account, nil
395: 
396: 	case <-ctx.Done():
397: 		oauth.Cancel()
398: 		return config.Account{}, fmt.Errorf("OAuth login timed out after 3 minutes")
399: 	}
400: }
