412: // saveValidatedAccount handles AES-256-GCM vault encryption, config persistence, and event emission.
413: func (a *App) saveValidatedAccount(tokenName string, patToken string, userInfo *githubapi.GitHubUserInfo, rateInfo *githubapi.RateLimitInfo) (config.Account, error) {
414: 	encPAT, err := a.cfg.EncryptPAT(patToken)
415: 	if err != nil {
416: 		return config.Account{}, fmt.Errorf("encrypt PAT: %w", err)
417: 	}
418: 
419: 	label := strings.TrimSpace(tokenName)
420: 	if label == "" {
421: 		if userInfo.Name != "" {
422: 			label = userInfo.Name
423: 		} else {
424: 			label = fmt.Sprintf("@%s", userInfo.Username)
425: 		}
426: 	}
427: 
428: 	email := strings.TrimSpace(userInfo.Email)
429: 	if email == "" {
430: 		email = fmt.Sprintf("%s@users.noreply.github.com", userInfo.Username)
431: 	}
432: 
433: 	// If account with this username already exists, update token, avatar and email
434: 	existing := a.cfg.FindAccountByUsername(userInfo.Username)
435: 	var account config.Account
436: 	if existing != nil {
437: 		account = *existing
438: 		account.Label = label
439: 		account.EncryptedPAT = encPAT
440: 		account.AvatarURL = userInfo.AvatarURL
441: 		account.Email = email
442: 		if err := a.cfg.UpdateAccount(account); err != nil {
443: 			return config.Account{}, fmt.Errorf("update account: %w", err)
444: 		}
445: 		a.github.InvalidateClient(account.ID)
446: 		if a.log != nil {
447: 			a.log.Info("auth", "updated existing GitHub account: @%s (%s)", account.Username, account.Label)
448: 		}
449: 	} else {
450: 		account = config.Account{
451: 			ID:           uuid.New().String(),
452: 			Label:        label,
453: 			Username:     userInfo.Username,
454: 			Email:        email,
455: 			EncryptedPAT: encPAT,
456: 			AvatarURL:    userInfo.AvatarURL,
457: 			CreatedAt:    time.Now(),
458: 		}
459: 		if err := a.cfg.AddAccount(account); err != nil {
460: 			return config.Account{}, fmt.Errorf("save account: %w", err)
461: 		}
462: 		if a.log != nil {
463: 			a.log.Info("auth", "registered new GitHub account: @%s (%s)", account.Username, account.Label)
464: 		}
465: 	}
466: 
467: 	a.emitEvent("config:updated", a.cfg.Config())
468: 	if rateInfo != nil {
469: 		a.emitEvent("account:ratelimit", map[string]interface{}{
470: 			"accountId": account.ID,
471: 			"remaining": rateInfo.Remaining,
472: 			"limit":     rateInfo.Limit,
473: 			"resetAt":   rateInfo.ResetAt.Format(time.RFC3339),
474: 			"used":      rateInfo.Used,
475: 		})
476: 	}
477: 
478: 	return account, nil
479: }
