534: 	if _, err := os.Stat(localPath); err != nil {
535: 		return fmt.Errorf("path does not exist: %s", localPath)
536: 	}
537: 
538: 	// Safety check: prevent watching shallow root paths
539: 	if !isSafePath(localPath) {
540: 		return fmt.Errorf("path %q is too shallow — please select a dedicated project directory", localPath)
541: 	}
542: 
543: 	home, _ := os.UserHomeDir()
544: 	backupDir := filepath.Join(home, ".gitsync", "backups", repoName)
545: 
546: 	repo := config.RepoConfig{
547: 		ID:         uuid.New().String(),
548: 		LocalPath:  filepath.Clean(localPath),
549: 		RemoteName: repoName,
550: 		AccountID:  accountID,
551: 		Visibility: visibility,
552: 		Enabled:    true,
553: 		Branch:     "main",
554: 		CommitMsg:  "chore: auto-sync {{timestamp}}",
555: 		BackupDir:  backupDir,
556: 		CreatedAt:  time.Now(),
557: 	}
558: 
559: 	if err := a.cfg.AddRepo(repo); err != nil {
560: 		return err
561: 	}
562: 
563: 	// Register with watcher service
564: 	a.watchSvc.AddRepo(&repo)
565: 	a.log.Info("app", "added repository: %s → %s", localPath, repoName)
566: 	return nil
