609: func (a *App) SelectDirectory() (resPath string, err error) {
610: 	defer func() {
611: 		if r := recover(); r != nil {
612: 			if a != nil && a.log != nil {
613: 				a.log.Warn("dialog", "recovered from SelectDirectory panic: %v", r)
614: 			}
615: 			resPath = ""
