617: 		}
618: 	}()
619: 
620: 	// 1. Check if a.ctx is nil
621: 	if a == nil || a.ctx == nil {
622: 		if a != nil && a.log != nil {
623: 			a.log.Warn("dialog", "cannot open folder dialog: runtime context is nil")
624: 		}
625: 		return "", fmt.Errorf("application runtime context is not ready")
626: 	}
627: 
628: 	// 2. On Windows, use the safe out-of-process folder dialog.
629: 	// In Windows Sandbox, WDAGUtilityAccount, and frameless Wails windows, in-process
630: 	// COM IFileDialog (wailsRuntime.OpenDirectoryDialog) triggers unrecoverable native
631: 	// 0xc0000005 access violations that terminate the process.
632: 	// The out-of-process dialog runs isolated, can never crash GitSync, and works in all Windows environments.
633: 	if stdRuntime.GOOS == "windows" {
634: 		if a != nil && a.log != nil {
635: 			a.log.Info("dialog", "prompting Windows folder dialog")
636: 		}
637: 		path := openSafeDirectoryDialog()
638: 		return path, nil
639: 	}
640: 
641: 	// 3. For non-Windows platforms (macOS / Linux), wrap Wails native directory dialog in a safe goroutine with panic recovery
642: 	type dialogResult struct {
643: 		path string
644: 		err  error
645: 	}
646: 
647: 	done := make(chan dialogResult, 1)
648: 
649: 	go func() {
650: 		defer func() {
651: 			if r := recover(); r != nil {
652: 				if a != nil && a.log != nil {
653: 					a.log.Warn("dialog", "recovered from native folder dialog goroutine panic: %v", r)
654: 				}
655: 				done <- dialogResult{path: "", err: nil}
656: 			}
657: 		}()
658: 
659: 		path, dlgErr := wailsRuntime.OpenDirectoryDialog(a.ctx, wailsRuntime.OpenDialogOptions{
660: 			Title: "Select Folder to Watch",
661: 		})
662: 		if dlgErr != nil {
663: 			if a != nil && a.log != nil {
664: 				a.log.Warn("dialog", "native folder dialog failed or was cancelled: %v", dlgErr)
665: 			}
666: 			done <- dialogResult{path: "", err: nil}
667: 			return
668: 		}
669: 
670: 		done <- dialogResult{path: path, err: nil}
671: 	}()
672: 
673: 	select {
674: 	case res := <-done:
675: 		return res.path, res.err
676: 	case <-time.After(3 * time.Minute):
677: 		if a != nil && a.log != nil {
678: 			a.log.Warn("dialog", "native folder dialog timed out waiting for user input")
679: 		}
680: 		return "", nil
681: 	}
