186: // EncryptPAT encrypts a plaintext PAT for storage using AES-256-GCM with a random nonce.
187: func (s *Store) EncryptPAT(plaintext string) (string, error) {
188: 	block, err := aes.NewCipher(s.key)
189: 	if err != nil {
190: 		return "", fmt.Errorf("create cipher: %w", err)
191: 	}
192: 	gcm, err := cipher.NewGCM(block)
193: 	if err != nil {
194: 		return "", fmt.Errorf("create gcm: %w", err)
195: 	}
196: 	nonce := make([]byte, gcm.NonceSize())
197: 	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
198: 		return "", fmt.Errorf("read random nonce: %w", err)
199: 	}
200: 	ciphertext := gcm.Seal(nonce, nonce, []byte(plaintext), nil)
201: 	return base64.StdEncoding.EncodeToString(ciphertext), nil
202: }
