204: // DecryptPAT decrypts a stored encrypted PAT using AES-256-GCM.
205: func (s *Store) DecryptPAT(encrypted string) (string, error) {
206: 	data, err := base64.StdEncoding.DecodeString(encrypted)
207: 	if err != nil {
208: 		return "", fmt.Errorf("base64 decode: %w", err)
209: 	}
210: 	block, err := aes.NewCipher(s.key)
211: 	if err != nil {
212: 		return "", fmt.Errorf("create cipher: %w", err)
213: 	}
214: 	gcm, err := cipher.NewGCM(block)
215: 	if err != nil {
216: 		return "", fmt.Errorf("create gcm: %w", err)
217: 	}
218: 	nonceSize := gcm.NonceSize()
219: 	if len(data) < nonceSize {
220: 		return "", fmt.Errorf("ciphertext too short: length %d, min %d", len(data), nonceSize)
221: 	}
222: 	nonce, ciphertext := data[:nonceSize], data[nonceSize:]
223: 	plaintext, err := gcm.Open(nil, nonce, ciphertext, nil)
224: 	if err != nil {
225: 		return "", fmt.Errorf("gcm decrypt failed: %w", err)
226: 	}
227: 	return string(plaintext), nil
228: }
