136: 	if info.IsDir() {
137: 		// If a directory was provided, check common git binary subpaths
138: 		subpaths := []string{
139: 			filepath.Join(target, "cmd", "git.exe"),
140: 			filepath.Join(target, "bin", "git.exe"),
141: 			filepath.Join(target, "git.exe"),
142: 			filepath.Join(target, "bin", "git"),
