93: 	}
94: 
95: 	dir := repo.LocalPath
96: 
97: 	// 1. Ensure initialized
98: 	if !e.exec.IsRepo(dir) {
99: 		if err := e.init(dir); err != nil {
100: 			return fmt.Errorf("git init: %w", err)
101: 		}
102: 	}
103: 
104: 	// 2. Configure local identity dynamically from account
105: 	if account != nil {
