113: 	// 3. Take safety snapshots (git lightweight ref and zip archive)
114: 	if err := e.Snapshot(repo); err != nil {
115: 		if e.log != nil {
116: 			e.log.Warn("gitengine", "snapshot skipped (non-fatal): %v", err)
117: 		}
118: 	}
119: 
120: 	// 4. Stage all changes
121: 	if _, err := e.exec.Run(dir, "add", "--all"); err != nil {
122: 		return fmt.Errorf("git add: %w", err)
123: 	}
124: 
125: 	// Guard against files exceeding GitHub's 100MB threshold (default 95MB safety limit)
126: 	_ = e.unstageLargeFiles(dir, 95*1024*1024)
127: 
128: 	// 5. Check if there's anything to commit
129: 	status, err := e.exec.Run(dir, "status", "--porcelain")
130: 	if err != nil {
131: 		return err
132: 	}
133: 	if strings.TrimSpace(status) == "" {
134: 		if e.log != nil {
135: 			e.log.Debug("gitengine", "[%s] nothing to commit", repo.RemoteName)
136: 		}
137: 		// If working tree is clean, we still attempt push in case unpushed commits exist locally
138: 		if e.exec.HasRemote(dir) {
139: 			return e.safePush(repo)
140: 		}
141: 		return nil
142: 	}
143: 
144: 	// 6. Automated commit with timestamp interpolation
145: 	msg := buildCommitMsg(repo.CommitMsg)
146: 	if _, err := e.exec.Run(dir, "commit", "-m", msg); err != nil {
147: 		return fmt.Errorf("git commit: %w", err)
