218: // unstageLargeFiles removes any staged files exceeding maxBytes from the current index.
219: func (e *Engine) unstageLargeFiles(dir string, maxBytes int64) error {
220: 	staged, err := e.exec.Run(dir, "diff", "--name-only", "--cached")
221: 	if err != nil {
222: 		return nil
223: 	}
224: 	for _, relPath := range strings.Split(strings.TrimSpace(staged), "\n") {
225: 		relPath = strings.TrimSpace(relPath)
226: 		if relPath == "" {
227: 			continue
228: 		}
229: 		fullPath := filepath.Join(dir, relPath)
230: 		info, err := os.Stat(fullPath)
231: 		if err != nil {
232: 			continue
233: 		}
234: 		if info.Size() > maxBytes {
235: 			if _, err := e.exec.Run(dir, "restore", "--staged", relPath); err != nil {
236: 				if _, resetErr := e.exec.Run(dir, "reset", "HEAD", relPath); resetErr != nil {
237: 					_, _ = e.exec.Run(dir, "rm", "--cached", relPath)
238: 				}
239: 			}
240: 			if e.log != nil {
241: 				e.log.Warn("gitengine", "unstaged large file exceeding %d MB: %s (%d MB)",
242: 					maxBytes/(1024*1024), relPath, info.Size()/(1024*1024))
