284: // extractZipArchive safely unpacks a zip archive into targetDir, protecting against Zip Slip.
285: func extractZipArchive(zipFile, targetDir string, progressCb func(string)) error {
286: 	reader, err := zip.OpenReader(zipFile)
287: 	if err != nil {
288: 		return fmt.Errorf("open zip archive: %w", err)
289: 	}
290: 	defer reader.Close()
291: 
292: 	totalFiles := len(reader.File)
293: 	cleanTarget := filepath.Clean(targetDir)
294: 
295: 	lastReport := time.Now()
296: 	for i, f := range reader.File {
297: 		// Prevent Zip Slip vulnerability
298: 		extractedPath := filepath.Join(cleanTarget, f.Name)
299: 		cleanExtracted := filepath.Clean(extractedPath)
300: 		if !strings.HasPrefix(cleanExtracted, cleanTarget+string(filepath.Separator)) && cleanExtracted != cleanTarget {
301: 			return fmt.Errorf("illegal file path in zip archive: %s", f.Name)
302: 		}
303: 
304: 		if f.FileInfo().IsDir() {
305: 			if err := os.MkdirAll(cleanExtracted, 0755); err != nil {
306: 				return fmt.Errorf("create dir %s: %w", cleanExtracted, err)
307: 			}
308: 			continue
309: 		}
310: 
311: 		// Ensure parent directory exists
312: 		if err := os.MkdirAll(filepath.Dir(cleanExtracted), 0755); err != nil {
313: 			return fmt.Errorf("create parent dir for %s: %w", cleanExtracted, err)
314: 		}
315: 
316: 		// Extract file contents
317: 		if err := extractZipFile(f, cleanExtracted); err != nil {
318: 			return fmt.Errorf("extract file %s: %w", f.Name, err)
319: 		}
320: 
321: 		if time.Since(lastReport) > 250*time.Millisecond || i == totalFiles-1 {
322: 			lastReport = time.Now()
323: 			pct := ((i + 1) * 100) / totalFiles
324: 			progressCb(fmt.Sprintf("Extracting Git components (%d%% - %d/%d files)...", pct, i+1, totalFiles))
325: 		}
326: 	}
327: 
328: 	return nil
329: }
330: 
331: func extractZipFile(f *zip.File, destPath string) error {
332: 	rc, err := f.Open()
333: 	if err != nil {
334: 		return err
335: 	}
336: 	defer rc.Close()
337: 
338: 	// Truncate or create target file
339: 	mode := f.Mode()
340: 	if mode == 0 {
341: 		mode = 0644
342: 	}
343: 	outFile, err := os.OpenFile(destPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, mode)
344: 	if err != nil {
345: 		return err
346: 	}
347: 	defer outFile.Close()
348: 
349: 	_, err = io.Copy(outFile, rc)
350: 	return err
351: }

