191: 	req, err := http.NewRequestWithContext(ctx, http.MethodPost, tokenEndpoint, strings.NewReader(params.Encode()))
192: 	if err != nil {
193: 		return "", fmt.Errorf("create token exchange request: %w", err)
194: 	}
195: 
196: 	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
197: 	req.Header.Set("Accept", "application/json")
198: 
199: 	client := &http.Client{Timeout: 15 * time.Second}
200: 	resp, err := client.Do(req)
201: 	if err != nil {
202: 		return "", fmt.Errorf("execute token exchange: %w", err)
203: 	}
204: 	defer resp.Body.Close()
205: 
206: 	bodyBytes, err := io.ReadAll(resp.Body)
207: 	if err != nil {
208: 		return "", fmt.Errorf("read token exchange response: %w", err)
209: 	}
210: 
211: 	var tokenResp OAuthTokenResponse
212: 	if err := json.Unmarshal(bodyBytes, &tokenResp); err != nil {
213: 		return "", fmt.Errorf("decode token exchange JSON: %w (body: %s)", err, string(bodyBytes))
214: 	}
215: 
216: 	if tokenResp.Error != "" {
217: 		desc := tokenResp.ErrorDescription
218: 		if desc == "" {
219: 			desc = tokenResp.Error
220: 		}
221: 		return "", fmt.Errorf("GitHub OAuth error: %s", desc)
222: 	}
223: 
224: 	if strings.TrimSpace(tokenResp.AccessToken) == "" {
225: 		return "", fmt.Errorf("GitHub returned empty access token")
226: 	}
227: 
228: 	return tokenResp.AccessToken, nil
