65: func (l *Logger) log(level Level, component, msg string) {
66: 	entry := Entry{
67: 		Level:     level,
68: 		Component: component,
69: 		Message:   msg,
70: 		Timestamp: time.Now().UTC().Format(time.RFC3339),
71: 	}
72: 	l.mu.Lock()
73: 	defer l.mu.Unlock()
74: 
75: 	// Ring buffer: drop oldest entry when full
76: 	if len(l.ring) >= l.ringSize {
77: 		l.ring = l.ring[1:]
78: 	}
79: 	l.ring = append(l.ring, entry)
