81: 	// Write to log file
82: 	line := fmt.Sprintf("%s [%-5s] [%s] %s\n",
83: 		entry.Timestamp, entry.Level, entry.Component, entry.Message)
84: 	if l.file != nil {
85: 		l.file.WriteString(line)
86: 		l.rotateIfNeeded()
87: 	}
