116: func (l *Logger) Recent(n int) []Entry {
117: 	l.mu.Lock()
118: 	defer l.mu.Unlock()
119: 	if n <= 0 || n >= len(l.ring) {
120: 		result := make([]Entry, len(l.ring))
121: 		copy(result, l.ring)
122: 		return result
123: 	}
124: 	result := make([]Entry, n)
