156: func (l *Logger) rotateIfNeeded() {
157: 	if l.file == nil || l.maxBytes == 0 {
158: 		return
159: 	}
160: 	info, err := l.file.Stat()
161: 	if err != nil || info.Size() < l.maxBytes {
162: 		return
163: 	}
164: 	l.file.Close()
165: 	l.file = nil
166: 
167: 	// Shift existing rotated files: .log.2 → .log.3, .log.1 → .log.2
168: 	for i := l.maxFiles - 1; i >= 1; i-- {
169: 		oldPath := fmt.Sprintf("%s.%d", l.filePath, i)
170: 		newPath := fmt.Sprintf("%s.%d", l.filePath, i+1)
171: 		os.Rename(oldPath, newPath)
172: 	}
173: 	// Rename current log to .log.1
174: 	os.Rename(l.filePath, l.filePath+".1")
175: 	l.openLogFile()
176: }

