14: // Debouncer manages per-key timers that fire after idleDuration of inactivity,
15: // but are bounded by maxWaitDuration to prevent infinite starvation during continuous writes.
16: type Debouncer struct {
17: 	mu              sync.Mutex
18: 	entries         map[string]*debounceEntry
19: 	idleDuration    time.Duration
20: 	maxWaitDuration time.Duration
21: }
22: 
23: // NewDebouncer creates a Debouncer with an idle delay and an optional hard trailing cap.
24: // If maxWait is not provided, it defaults to max(idleDuration*4, 120s).
25: func NewDebouncer(idleDuration time.Duration, maxWait ...time.Duration) *Debouncer {
26: 	if idleDuration <= 0 {
27: 		idleDuration = 30 * time.Second
28: 	}
29: 
30: 	maxWaitDuration := idleDuration * 4
31: 	if len(maxWait) > 0 && maxWait[0] > 0 {
32: 		maxWaitDuration = maxWait[0]
33: 	}
34: 	if maxWaitDuration < idleDuration {
35: 		maxWaitDuration = idleDuration * 4
36: 	}
37: 
38: 	return &Debouncer{
39: 		entries:         make(map[string]*debounceEntry),
40: 		idleDuration:    idleDuration,
41: 		maxWaitDuration: maxWaitDuration,
42: 	}
43: }
44: 
45: // Schedule queues or resets a debounced execution for a key.
46: // If the key has experienced continuous events exceeding maxWaitDuration since the first event,
47: // the callback is executed immediately to prevent debounce starvation.
48: func (d *Debouncer) Schedule(key string, fn func()) {
49: 	d.mu.Lock()
50: 	defer d.mu.Unlock()
51: 
52: 	now := time.Now()
53: 	entry, exists := d.entries[key]
54: 
55: 	if exists {
56: 		if entry.timer != nil {
57: 			entry.timer.Stop()
58: 		}
59: 		entry.callback = fn
60: 
61: 		// Check if we have hit or passed the trailing max-wait cap
62: 		elapsed := now.Sub(entry.firstEvent)
63: 		if elapsed >= d.maxWaitDuration {
64: 			// Starvation threshold reached: fire immediately
65: 			delete(d.entries, key)
66: 			go fn()
67: 			return
68: 		}
69: 
70: 		// Calculate remaining time before hard cap
71: 		remaining := d.maxWaitDuration - elapsed
72: 		delay := d.idleDuration
73: 		if remaining < delay {
74: 			delay = remaining
75: 		}
76: 
77: 		entry.timer = time.AfterFunc(delay, func() {
78: 			d.trigger(key)
79: 		})
80: 		return
81: 	}
82: 
83: 	// First event in burst
84: 	newEntry := &debounceEntry{
85: 		firstEvent: now,
86: 		callback:   fn,
87: 	}
88: 	newEntry.timer = time.AfterFunc(d.idleDuration, func() {
89: 		d.trigger(key)
90: 	})
91: 	d.entries[key] = newEntry
92: }
93: 
94: func (d *Debouncer) trigger(key string) {
95: 	d.mu.Lock()
96: 	entry, exists := d.entries[key]
97: 	if !exists {
98: 		d.mu.Unlock()
99: 		return
100: 	}
101: 	fn := entry.callback
102: 	delete(d.entries, key)
103: 	d.mu.Unlock()
104: 
105: 	if fn != nil {
106: 		fn()
107: 	}
108: }
109: 
110: // Pending reports whether a key currently has a pending debounced timer.
111: func (d *Debouncer) Pending(key string) bool {
112: 	d.mu.Lock()
113: 	defer d.mu.Unlock()
114: 	_, exists := d.entries[key]
115: 	return exists
116: }
117: 
118: // Cancel stops and removes a pending timer for a specific key.
119: func (d *Debouncer) Cancel(key string) {
120: 	d.mu.Lock()
121: 	defer d.mu.Unlock()
122: 	if entry, exists := d.entries[key]; exists {
123: 		if entry.timer != nil {
124: 			entry.timer.Stop()
125: 		}
126: 		delete(d.entries, key)
127: 	}
128: }
129: 
130: // CancelAll cancels all pending timers across all keys.
131: func (d *Debouncer) CancelAll() {
132: 	d.mu.Lock()
133: 	defer d.mu.Unlock()
134: 	for _, entry := range d.entries {
135: 		if entry.timer != nil {
136: 			entry.timer.Stop()
137: 		}
138: 	}
139: 	d.entries = make(map[string]*debounceEntry)
140: }

