131: 	s.debouncer.CancelAll()
132: 	if s.watcher != nil {
133: 		_ = s.watcher.Close()
134: 	}
135: 
136: 	// Drain active sync goroutines with graceful timeout
137: 	doneCh := make(chan struct{})
138: 	go func() {
139: 		s.activeSyncs.Wait()
140: 		close(doneCh)
141: 	}()
142: 
143: 	select {
144: 	case <-doneCh:
145: 		s.log.Info("watcher", "all active syncs completed cleanly")
146: 	case <-ctx.Done():
147: 		s.log.Warn("watcher", "stop context timed out waiting for active syncs")
148: 	}
