205: func (s *Service) registerRepo(repo *config.RepoConfig) {
206: 	// 1. Automatic git init if not already a repository
207: 	s.git.EnsureInit(repo)
208: 	ensureDefaultGitignore(repo.LocalPath)
209: 
210: 	// 2. Register recursive directory paths with fsnotify
211: 	if err := s.registerPath(repo.ID, repo.LocalPath); err != nil {
212: 		s.log.Error("watcher", "failed to watch %s: %v", repo.LocalPath, err)
213: 		return
214: 	}
215: 
216: 	// 3. Initialize state machine for this repo
217: 	s.mu.Lock()
218: 	if _, exists := s.states[repo.ID]; !exists {
219: 		s.states[repo.ID] = &repoSyncState{
220: 			status: RepoStatus{
221: 				RepoID:     repo.ID,
222: 				LocalPath:  repo.LocalPath,
223: 				RemoteName: repo.RemoteName,
224: 				State:      "idle",
225: 			},
226: 		}
227: 	}
228: 	s.mu.Unlock()
229: 
230: 	s.log.Info("watcher", "watching: %s → %s", repo.LocalPath, repo.RemoteName)
231: }
