233: func (s *Service) registerPath(repoID, root string) error {
234: 	return filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
235: 		if err != nil {
236: 			return nil
237: 		}
238: 		if !d.IsDir() {
239: 			return nil
240: 		}
241: 		if isGitPath(path) || isIgnoredDir(d.Name()) {
242: 			return filepath.SkipDir
243: 		}
244: 		if s.watcher != nil {
245: 			if watchErr := s.watcher.Add(path); watchErr != nil {
246: 				return nil
247: 			}
248: 		}
249: 		s.mu.Lock()
250: 		s.pathToRepo[path] = repoID
251: 		s.mu.Unlock()
252: 		return nil
253: 	})
254: }
