256: func (s *Service) eventLoop(ctx context.Context) {
257: 	defer func() {
258: 		if s.watcher != nil {
259: 			_ = s.watcher.Close()
260: 		}
261: 	}()
262: 
263: 	for {
264: 		select {
265: 		case <-ctx.Done():
266: 			s.debouncer.CancelAll()
267: 			return
268: 
269: 		case event, ok := <-s.watcher.Events:
270: 			if !ok {
271: 				return
272: 			}
273: 			s.handleEvent(event)
274: 
275: 		case err, ok := <-s.watcher.Errors:
276: 			if !ok {
277: 				return
278: 			}
279: 			s.log.Error("watcher", "fsnotify error: %v", err)
280: 		}
281: 	}
282: }
