284: func (s *Service) handleEvent(event fsnotify.Event) {
285: 	// Ignore permission / metadata-only changes
286: 	if event.Has(fsnotify.Chmod) {
287: 		return
288: 	}
289: 
290: 	// 1. Strict .git sanitization: reject any path containing .git
291: 	if isGitPath(event.Name) {
292: 		return
293: 	}
294: 
295: 	// 2. Reject noise file names and extensions
296: 	base := filepath.Base(event.Name)
297: 	if isNoisePath(base) {
298: 		return
299: 	}
300: 
301: 	// 3. Dynamically watch and auto-init newly created subdirectories
302: 	if event.Has(fsnotify.Create) {
303: 		if info, err := os.Stat(event.Name); err == nil && info.IsDir() {
304: 			if !isIgnoredDir(base) {
305: 				repoID := s.findRepoForPath(filepath.Dir(event.Name))
306: 				if repoID != "" {
307: 					_ = s.registerPath(repoID, event.Name)
308: 					if repo := s.cfg.FindRepo(repoID); repo != nil {
309: 						// Auto git init on newly discovered workspace subfolders if not already part of a repo
310: 						_ = s.git.EnsureInitPath(event.Name, repo)
311: 					}
312: 				}
313: 			}
314: 			return
315: 		}
316: 	}
317: 
318: 	// 4. Check global pause
319: 	if s.cfg.Config().Preferences.GlobalPause {
320: 		return
321: 	}
322: 
323: 	// 5. Resolve repo ID for the changed file path
324: 	repoID := s.findRepoForPath(filepath.Dir(event.Name))
325: 	if repoID == "" {
326: 		repoID = s.findRepoForPath(event.Name)
327: 	}
328: 	if repoID == "" {
329: 		return
330: 	}
331: 
332: 	// 6. Check per-repo enabled state
333: 	repo := s.cfg.FindRepo(repoID)
334: 	if repo == nil || !repo.Enabled {
335: 		return
336: 	}
337: 
338: 	// 7. Update pending file count & debouncing state
339: 	s.mu.Lock()
340: 	if st, ok := s.states[repoID]; ok {
341: 		st.status.PendingFiles++
342: 		if st.status.State == "idle" {
343: 			st.status.State = "debouncing"
344: 		}
345: 	}
346: 	s.mu.Unlock()
347: 	s.emitStatuses()
348: 
349: 	// 8. Schedule debounced execution with trailing cap protection
350: 	s.debouncer.Schedule(repoID, func() {
351: 		s.activeSyncs.Add(1)
352: 		go func() {
353: 			defer s.activeSyncs.Done()
354: 			s.runSync(repoID)
355: 		}()
356: 	})
357: }
