359: // runSync executes the sync workflow with mutual exclusion and the dirty/needsResync flag.
360: func (s *Service) runSync(repoID string) {
361: 	s.mu.RLock()
362: 	state, exists := s.states[repoID]
363: 	s.mu.RUnlock()
364: 	if !exists {
365: 		return
366: 	}
367: 
368: 	// Attempt to acquire per-repo execution lock
369: 	if !state.mu.TryLock() {
370: 		// Another sync is currently in progress: flag dirty so it immediately re-syncs when finished!
371: 		state.needsResync = true
372: 		s.log.Debug("watcher", "[%s] sync currently active; queued follow-up sync", repoID)
373: 		return
374: 	}
375: 	defer state.mu.Unlock()
376: 
377: 	// Loop as long as changes arrive while syncing (needsResync)
378: 	for {
379: 		state.needsResync = false
380: 
381: 		s.mu.Lock()
382: 		state.status.State = "syncing"
383: 		state.status.PendingFiles = 0
384: 		s.mu.Unlock()
385: 		s.emitStatuses()
386: 
387: 		repo := s.cfg.FindRepo(repoID)
388: 		if repo == nil {
389: 			return
390: 		}
391: 		account := s.cfg.FindAccount(repo.AccountID)
392: 
393: 		// File settling probe: brief pause to allow external file write handles to flush
394: 		time.Sleep(50 * time.Millisecond)
395: 
396: 		syncCtx, syncCancel := context.WithTimeout(context.Background(), 2*time.Minute)
397: 		err := s.git.Sync(syncCtx, repo, account, s.github)
398: 		syncCancel()
399: 
400: 		s.mu.Lock()
401: 		if err != nil {
402: 			errStr := err.Error()
403: 			if strings.Contains(errStr, "offline") || strings.Contains(errStr, "Could not resolve host") {
404: 				state.status.State = "offline"
405: 			} else if strings.Contains(errStr, "conflict") {
406: 				state.status.State = "conflict"
407: 				if s.emit != nil {
408: 					s.emit("toast:notify", map[string]interface{}{
409: 						"id":        fmt.Sprintf("conflict-%s-%d", repo.RemoteName, time.Now().UnixNano()),
410: 						"type":      "conflict",
411: 						"title":     "Git Conflict Isolated",
412: 						"message":   fmt.Sprintf("[%s] Changes safely preserved in conflict branch", repo.RemoteName),
413: 						"repoName":  repo.RemoteName,
414: 						"timestamp": time.Now().UTC().Format(time.RFC3339),
415: 					})
416: 				}
417: 			} else {
418: 				state.status.State = "error"
419: 			}
420: 			state.status.LastError = errStr
421: 			s.log.Error("sync", "[%s] sync failed: %v", repo.RemoteName, err)
422: 		} else {
423: 			state.status.State = "idle"
424: 			state.status.LastSyncAt = time.Now()
425: 			state.status.LastError = ""
426: 			s.log.Info("sync", "[%s] synced successfully", repo.RemoteName)
427: 			if s.emit != nil {
428: 				s.emit("toast:notify", map[string]interface{}{
429: 					"id":        fmt.Sprintf("sync-%s-%d", repo.RemoteName, time.Now().UnixNano()),
430: 					"type":      "success",
431: 					"title":     "Repository Synced",
432: 					"message":   fmt.Sprintf("[%s] Synced successfully to GitHub", repo.RemoteName),
433: 					"repoName":  repo.RemoteName,
434: 					"timestamp": time.Now().UTC().Format(time.RFC3339),
435: 				})
436: 			}
437: 		}
438: 		s.mu.Unlock()
439: 		s.emitStatuses()
440: 
441: 		// If no new events arrived during sync, we are finished!
442: 		if !state.needsResync {
443: 			break
444: 		}
445: 		s.log.Info("sync", "[%s] dirty flag set during sync, executing trailing pass", repo.RemoteName)
446: 	}
447: }
