449: func (s *Service) findRepoForPath(path string) string {
450: 	s.mu.RLock()
451: 	defer s.mu.RUnlock()
452: 
453: 	clean := filepath.Clean(path)
454: 	// Check exact match
455: 	if id, ok := s.pathToRepo[clean]; ok {
456: 		return id
457: 	}
458: 
459: 	// Check ancestors
460: 	for p := clean; p != filepath.Dir(p); p = filepath.Dir(p) {
461: 		if id, ok := s.pathToRepo[p]; ok {
462: 			return id
463: 		}
464: 	}
465: 	return ""
466: }
