476: // isGitPath returns true if the path is inside or is a .git directory.
477: func isGitPath(path string) bool {
478: 	clean := filepath.ToSlash(filepath.Clean(path))
479: 	return strings.HasSuffix(clean, "/.git") ||
480: 		strings.Contains(clean, "/.git/") ||
481: 		filepath.Base(clean) == ".git"
482: }
483: 
484: // isIgnoredDir returns true for heavy build or dependency directories.
485: func isIgnoredDir(base string) bool {
486: 	switch base {
487: 	case ".git", "node_modules", "vendor", "__pycache__", ".venv",
488: 		".idea", ".vscode", "dist", "build", "target", ".next", ".nuxt", "bin", "obj":
489: 		return true
490: 	}
491: 	return strings.HasPrefix(base, ".")
492: }
493: 
494: // isNoisePath returns true for temporary, editor, or system noise files.
495: func isNoisePath(base string) bool {
496: 	noiseSuffixes := []string{
497: 		".tmp", ".swp", ".lock", "~", ".bak", ".crdownload",
498: 		".part", ".ds_store", "thumbs.db", "desktop.ini",
499: 	}
500: 	noisePrefixes := []string{".", "#", "~$"}
501: 
502: 	lower := strings.ToLower(base)
503: 	for _, sfx := range noiseSuffixes {
504: 		if strings.HasSuffix(lower, sfx) {
505: 			return true
506: 		}
507: 	}
508: 	for _, pfx := range noisePrefixes {
509: 		if strings.HasPrefix(base, pfx) {
510: 			return true
511: 		}
512: 	}
513: 	return false
514: }
515: 
516: // ensureDefaultGitignore creates a curated .gitignore if one does not exist.
517: func ensureDefaultGitignore(repoPath string) {
518: 	gitignorePath := filepath.Join(repoPath, ".gitignore")
519: 	if _, err := os.Stat(gitignorePath); err == nil {
520: 		return
521: 	}
522: 
523: 	defaultContent := `# GitSync default exclusions
524: node_modules/
525: vendor/
526: __pycache__/
527: *.pyc
528: .venv/
529: dist/
530: build/
531: .DS_Store
532: Thumbs.db
533: *.tmp
534: *.swp
535: *.log
536: .env
537: .env.local
538: `
539: 	_ = os.WriteFile(gitignorePath, []byte(defaultContent), 0644)
540: }

