7: 
8:   const dismissToast = useCallback((id: string) => {
9:     setToasts((prev) => prev.filter((t) => t.id !== id));
10:   }, []);
11: 
12:   const addToast = useCallback((toast: Omit<ToastMessage, 'id'> & { id?: string }) => {
13:     const id = toast.id || `toast-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`;
14:     const duration = toast.duration ?? 4500;
15:     const newToast: ToastMessage = { ...toast, id, duration };
16: 
17:     setToasts((prev) => [...prev.slice(-4), newToast]); // Keep up to 5 concurrent toasts
18: 
19:     if (duration > 0) {
20:       setTimeout(() => {
21:         dismissToast(id);
22:       }, duration);
23:     }
24:   }, [dismissToast]);
