//go:build windows

package autostart

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"golang.org/x/sys/windows/registry"
)

const (
	runRegistryPath = `Software\Microsoft\Windows\CurrentVersion\Run`
	appValueName    = "GitSync"
)

// Set enables or disables launching GitSync automatically on Windows user login
// by managing HKCU\Software\Microsoft\Windows\CurrentVersion\Run.
func Set(enabled bool, customExePath ...string) error {
	k, _, err := registry.CreateKey(registry.CURRENT_USER, runRegistryPath, registry.SET_VALUE|registry.QUERY_VALUE)
	if err != nil {
		return fmt.Errorf("open startup registry key: %w", err)
	}
	defer k.Close()

	if !enabled {
		err = k.DeleteValue(appValueName)
		if err != nil && err != registry.ErrNotExist {
			return fmt.Errorf("remove startup registry value: %w", err)
		}
		return nil
	}

	exePath := ""
	if len(customExePath) > 0 && strings.TrimSpace(customExePath[0]) != "" {
		exePath = strings.TrimSpace(customExePath[0])
	} else {
		resolved, err := os.Executable()
		if err != nil {
			return fmt.Errorf("resolve executable path: %w", err)
		}
		exePath = resolved
	}

	if abs, err := filepath.Abs(exePath); err == nil {
		exePath = abs
	}

	cmdValue := fmt.Sprintf(`"%s" --minimized`, exePath)
	if err := k.SetStringValue(appValueName, cmdValue); err != nil {
		return fmt.Errorf("set startup registry value: %w", err)
	}
	return nil
}

// IsEnabled checks whether the GitSync startup value exists in HKCU\...\Run.
func IsEnabled() (bool, error) {
	k, err := registry.OpenKey(registry.CURRENT_USER, runRegistryPath, registry.QUERY_VALUE)
	if err != nil {
		if err == registry.ErrNotExist {
			return false, nil
		}
		return false, err
	}
	defer k.Close()

	val, _, err := k.GetStringValue(appValueName)
	if err != nil {
		if err == registry.ErrNotExist {
			return false, nil
		}
		return false, err
	}
	return strings.TrimSpace(val) != "", nil
}

//go:build !windows

package autostart

import "sync"

var (
	mu          sync.RWMutex
	mockEnabled bool
)

// Set is a no-op stub for non-Windows platforms.
func Set(enabled bool, _ ...string) error {
	mu.Lock()
	mockEnabled = enabled
	mu.Unlock()
	return nil
}

// IsEnabled reports the in-memory autostart state on non-Windows platforms.
func IsEnabled() (bool, error) {
	mu.RLock()
	defer mu.RUnlock()
	return mockEnabled, nil
}

package autostart

import (
	"testing"
)

func TestAutoStartSetAndCheck(t *testing.T) {
	orig, _ := IsEnabled()
	defer func() {
		_ = Set(orig)
	}()

	// Enable with a test executable path
	if err := Set(true, `C:\Program Files\GitSync\GitSync.exe`); err != nil {
		t.Fatalf("Set(true) failed: %v", err)
	}

	enabled, err := IsEnabled()
	if err != nil {
		t.Fatalf("IsEnabled() after Set(true) failed: %v", err)
	}
	if !enabled {
		t.Errorf("expected IsEnabled() to be true after Set(true)")
	}

	// Disable
	if err := Set(false); err != nil {
		t.Fatalf("Set(false) failed: %v", err)
	}

	enabledAfter, err := IsEnabled()
	if err != nil {
		t.Fatalf("IsEnabled() after Set(false) failed: %v", err)
	}
	if enabledAfter {
		t.Errorf("expected IsEnabled() to be false after Set(false)")
	}
}

