import { useState, useEffect, useRef } from 'react';
import { CloseIcon, AlertIcon, FolderIcon } from './Icons';
import { useWailsEvent } from '../hooks/useWailsEvents';

interface Props {
  onAdd: (localPath: string, repoName: string, accountId: string, visibility: 'public' | 'private') => Promise<void>;
  onClose: () => void;
  accounts: Array<{ id: string; label: string; username: string }>;
  onOpenFolder: () => Promise<string>;
  initialFolderPath?: string;
}

export function AddRepoModal({ onAdd, onClose, accounts, onOpenFolder, initialFolderPath }: Props) {
  const [localPath, setLocalPath] = useState('');
  const [repoName, setRepoName] = useState('');
  const [repoNameManuallyEdited, setRepoNameManuallyEdited] = useState(false);
  const [accountId, setAccountId] = useState(accounts[0]?.id ?? '');
  const [visibility, setVisibility] = useState<'public' | 'private'>('private');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [browseWarning, setBrowseWarning] = useState('');
  const [isDragging, setIsDragging] = useState(false);
  const dragCounter = useRef(0);

  const suggestRepoNameFromPath = (folderPath: string): string => {
    const parts = folderPath.replace(/\\/g, '/').split('/').filter(Boolean);
    const tail = parts[parts.length - 1] ?? '';
    return tail.toLowerCase().replace(/[^a-z0-9-_.]/g, '-');
  };

  const applyFolderPath = (rawPath: string) => {
    if (!rawPath || typeof rawPath !== 'string') return;
    let cleanPath = rawPath.trim();
    if (cleanPath.startsWith('file:///')) {
      try {
        cleanPath = decodeURIComponent(cleanPath.replace(/^file:\/\/\//, '')).replace(/\//g, '\\');
      } catch {
        // ignore URI decode issues
      }
    }
    if (!cleanPath) return;

    setLocalPath(cleanPath);
    setError('');
    setBrowseWarning('');

    const suggested = suggestRepoNameFromPath(cleanPath);
    if (suggested && (!repoNameManuallyEdited || !repoName)) {
      setRepoName(suggested);
    }
  };

  const applyFolderPathRef = useRef(applyFolderPath);
  applyFolderPathRef.current = applyFolderPath;

  // Apply initialFolderPath if modal opened via window drop
  useEffect(() => {
    if (initialFolderPath) {
      applyFolderPathRef.current(initialFolderPath);
    }
  }, [initialFolderPath]);

  // Listen to backend-resolved directory drops ("folder:dropped")
  useWailsEvent<string>('folder:dropped', (droppedDir) => {
    if (droppedDir && typeof droppedDir === 'string') {
      applyFolderPathRef.current(droppedDir);
      setIsDragging(false);
      dragCounter.current = 0;
    }
  });

  // Also listen directly to Wails native "wails:file-drop" event
  useEffect(() => {
    const runtime = (window as any).runtime;
    if (!runtime?.EventsOn) return;

    const cancel = runtime.EventsOn('wails:file-drop', (_x: number, _y: number, paths: string[]) => {
      if (Array.isArray(paths) && paths.length > 0 && paths[0]) {
        applyFolderPathRef.current(paths[0]);
        setIsDragging(false);
        dragCounter.current = 0;
      }
    });

    return () => {
      if (typeof cancel === 'function') {
        try { cancel(); } catch {}
      }
    };
  }, []);

  const hasFilesOrText = (dt: DataTransfer | null): boolean => {
    if (!dt || !dt.types) return false;
    return (
      dt.types.includes('Files') ||
      dt.types.includes('text/plain') ||
      dt.types.includes('text/uri-list')
    );
  };

  const handleDragEnter = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    dragCounter.current += 1;
    if (hasFilesOrText(e.dataTransfer)) {
      setIsDragging(true);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (hasFilesOrText(e.dataTransfer)) {
      e.dataTransfer.dropEffect = 'copy';
      if (!isDragging) setIsDragging(true);
    }
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    dragCounter.current = Math.max(0, dragCounter.current - 1);
    if (dragCounter.current === 0) {
      setIsDragging(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
    dragCounter.current = 0;

    const dt = e.dataTransfer;
    if (!dt) return;

    // 1. Collect dropped File objects
    const files: File[] = [];
    if (dt.items && dt.items.length > 0) {
      for (let i = 0; i < dt.items.length; i++) {
        const item = dt.items[i];
        if (item.kind === 'file') {
          const f = item.getAsFile();
          if (f) files.push(f);
        }
      }
    }
    if (files.length === 0 && dt.files && dt.files.length > 0) {
      for (let i = 0; i < dt.files.length; i++) {
        files.push(dt.files[i]);
      }
    }

    // 2. In WebView2 on Windows, send File objects to Wails native COM path resolver
    if (files.length > 0 && (window as any).chrome?.webview?.postMessageWithAdditionalObjects) {
      (window as any).chrome.webview.postMessageWithAdditionalObjects('file:drop:0:0', files);
      return;
    }

    // 3. Fallback: check direct file.path property if present
    if (files.length > 0) {
      const directPath = (files[0] as any)?.path || (files[0] as any)?.webkitRelativePath;
      if (directPath) {
        applyFolderPath(directPath);
        return;
      }
    }

    // 4. Fallback: check dragged text / URI list
    const textData = dt.getData('text/plain') || dt.getData('text/uri-list');
    if (textData && textData.trim()) {
      applyFolderPath(textData.trim());
    }
  };

  const handleBrowse = async () => {
    setBrowseWarning('');
    try {
      const path = await onOpenFolder();
      if (path && typeof path === 'string' && path.trim().length > 0) {
        applyFolderPath(path);
      }
    } catch {
      setBrowseWarning('Native folder dialog is unavailable in this environment. You can type, paste, or drop the path directly.');
    }
  };

  const handleManualPathChange = (val: string) => {
    setLocalPath(val);
    setError('');
    const suggested = suggestRepoNameFromPath(val);
    if (suggested && (!repoNameManuallyEdited || !repoName)) {
      setRepoName(suggested);
    }
  };

  const handlePasteClipboard = async () => {
    try {
      const text = await navigator.clipboard.readText();
      if (text) {
        applyFolderPath(text.trim());
      }
    } catch {
      // ignore clipboard error
    }
  };

  const handleSubmit = async () => {
    if (!localPath.trim()) { setError('Please specify a local folder path'); return; }
    if (!repoName.trim()) { setError('Repository name is required'); return; }
    if (!accountId) { setError('Please add a GitHub account first'); return; }

    setLoading(true);
    setError('');
    try {
      await onAdd(localPath.trim(), repoName.trim(), accountId, visibility);
      onClose();
    } catch (e: any) {
      setError(e?.message ?? 'Failed to add repository');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm animate-fade-in"
      data-wails-no-drag=""
      style={{ '--wails-drop-target': 'drop' } as React.CSSProperties}
      onDragEnter={handleDragEnter}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <div className="card max-w-[480px] w-full max-h-[90vh] overflow-y-auto p-6 space-y-5 shadow-2xl shadow-black/50 animate-slide-up relative">
        <div className="flex items-center justify-between">
          <h2 className="text-text-primary font-semibold text-base">Add Repository</h2>
          <button onClick={onClose} className="text-text-muted hover:text-text-primary transition-colors p-1 rounded-md">
            <CloseIcon className="w-4 h-4" />
          </button>
        </div>

        {/* Folder picker with Drag & Drop */}
        <div>
          <div className="flex items-center justify-between mb-1">
            <label className="block text-xs text-text-muted">Local Folder</label>
            <span className="text-[10px] text-text-muted/70">drag & drop folder or paste</span>
          </div>
          <div
            className={`relative rounded-md transition-all ${
              isDragging ? 'ring-2 ring-accent' : ''
            }`}
            style={{ '--wails-drop-target': 'drop' } as React.CSSProperties}
            onDragEnter={handleDragEnter}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
          >
            <div className="flex gap-2">
              <input
                id="input-folder-path"
                className={`input font-mono text-xs flex-1 transition-all ${
                  isDragging ? 'border-accent bg-accent/5' : ''
                }`}
                placeholder={isDragging ? 'Release folder here to set path…' : 'Type, paste, or drop a folder…'}
                value={localPath}
                onChange={e => handleManualPathChange(e.target.value)}
                onDragOver={handleDragOver}
                onDrop={handleDrop}
                data-wails-no-drag=""
              />
              <button
                type="button"
                onClick={handlePasteClipboard}
                className="btn-ghost border border-border px-2 text-xs shrink-0"
                title="Paste path from clipboard"
                data-wails-no-drag=""
              >
                Paste
              </button>
              <button
                type="button"
                onClick={handleBrowse}
                className="btn-ghost border border-border shrink-0 flex items-center gap-1.5"
                data-wails-no-drag=""
              >
                <FolderIcon className="w-3.5 h-3.5 text-text-muted" />
                <span>Browse</span>
              </button>
            </div>
            {isDragging && (
              <div className="absolute inset-0 rounded-md border-2 border-dashed border-accent bg-[#0d1116]/95 backdrop-blur-xs flex items-center justify-center gap-2 text-accent text-xs font-medium z-20 pointer-events-none animate-pulse">
                <FolderIcon className="w-4 h-4" />
                <span>Drop folder here to select</span>
              </div>
            )}
          </div>
          {browseWarning && (
            <p className="text-amber-400 text-[11px] mt-1.5 flex items-center gap-1.5">
              <AlertIcon className="w-3.5 h-3.5 shrink-0" />
              <span>{browseWarning}</span>
            </p>
          )}
        </div>

        {/* Repo name */}
        <div>
          <label className="block text-xs text-text-muted mb-1">GitHub Repository Name</label>
          <input
            id="input-repo-name"
            className="input font-mono"
            placeholder="my-project"
            value={repoName}
            onChange={e => {
              const nextVal = e.target.value.toLowerCase().replace(/\s+/g, '-');
              setRepoName(nextVal);
              setRepoNameManuallyEdited(Boolean(nextVal));
            }}
            data-wails-no-drag=""
          />
          <p className="text-text-disabled text-xs mt-1">
            Will be created at github.com/{accounts.find(a => a.id === accountId)?.username ?? '…'}/{repoName || '…'}
          </p>
        </div>

        {/* Account selector */}
        <div>
          <label className="block text-xs text-text-muted mb-1">GitHub Account</label>
          {accounts.length === 0 ? (
            <p className="text-status-error text-xs">No accounts configured. Add one in Settings → Accounts.</p>
          ) : (
            <select
              id="select-account"
              className="input"
              value={accountId}
              onChange={e => setAccountId(e.target.value)}
              data-wails-no-drag=""
            >
              {accounts.map(a => (
                <option key={a.id} value={a.id}>{a.label} (@{a.username})</option>
              ))}
            </select>
          )}
        </div>

        {/* Visibility */}
        <div>
          <label className="block text-xs text-text-muted mb-2">Visibility</label>
          <div className="flex gap-3" data-wails-no-drag="">
            {(['private', 'public'] as const).map(v => (
              <label
                key={v}
                className={`flex items-center gap-2 px-3 py-2 rounded-lg border cursor-pointer transition-all ${
                  visibility === v
                    ? 'border-accent/50 bg-accent/10 text-accent'
                    : 'border-border text-text-muted hover:border-border'
                }`}
              >
                <input
                  type="radio"
                  name="visibility"
                  value={v}
                  checked={visibility === v}
                  onChange={() => setVisibility(v)}
                  className="accent-accent"
                />
                <span className="text-sm capitalize">{v === 'private' ? 'Private' : 'Public'}</span>
              </label>
            ))}
          </div>
        </div>

        {error && <p className="text-status-error text-xs">{error}</p>}

        <div className="flex gap-3 justify-end pt-1" data-wails-no-drag="">
          <button onClick={onClose} className="btn-ghost">Cancel</button>
          <button onClick={handleSubmit} disabled={loading || accounts.length === 0} className="btn-primary">
            {loading ? 'Adding…' : 'Add Repository'}
          </button>
        </div>
      </div>
    </div>
  );
}

