241: func (a *App) calculateTrayMetrics() tray.Metrics {
242: 	if a.cfg == nil || a.watchSvc == nil {
243: 		return tray.Metrics{}
244: 	}
245: 	cfg := a.cfg.Config()
246: 	statuses := a.watchSvc.Statuses()
247: 
248: 	m := tray.Metrics{
249: 		TotalRepos: len(cfg.Repos),
250: 		IsPaused:   cfg.Preferences.GlobalPause,
251: 	}
252: 
253: 	for _, r := range cfg.Repos {
254: 		if r.Enabled {
255: 			m.ActiveRepos++
256: 		}
257: 	}
258: 
259: 	for _, st := range statuses {
260: 		if st.State == "syncing" {
261: 			m.Syncing++
262: 		}
263: 		if st.State == "conflict" {
264: 			m.Conflicts++
265: 		}
266: 		if st.PendingFiles > 0 || st.State == "debouncing" {
267: 			m.PendingSyncs += st.PendingFiles
268: 			if st.PendingFiles == 0 {
269: 				m.PendingSyncs++
270: 			}
271: 		}
272: 	}
273: 
274: 	return m
275: }
