// Recent returns the last n log entries from the ring buffer.
func (l *Logger) Recent(n int) []Entry {
	l.mu.Lock()
	defer l.mu.Unlock()
	if n <= 0 || n >= len(l.ring) {
		result := make([]Entry, len(l.ring))
		copy(result, l.ring)
		return result
	}
	result := make([]Entry, n)
	copy(result, l.ring[len(l.ring)-n:])
	return result
}

// Clear empties the in-memory log ring buffer.
func (l *Logger) Clear() {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.ring = l.ring[:0]
}

