	pauseTitle, pauseTooltip := PauseMenuTitle(initialPaused)
	mPause := systray.AddMenuItemCheckbox(
		pauseTitle,
		pauseTooltip,
		initialPaused,
	)
	systray.AddSeparator()
	mQuit := systray.AddMenuItem("Quit GitSync", "Exit the application completely")

