}

func (m *Manager) menuLoop(mOpen, mSyncAll, mPause, mQuit *systray.MenuItem) {
	for {
		select {
		case <-mOpen.ClickedCh:
			m.show()

		case <-mSyncAll.ClickedCh:
			m.triggerSyncAll()

		case <-mPause.ClickedCh:
			m.toggleGlobalPause()

		case <-mQuit.ClickedCh:
