// Manager holds references needed for tray menu actions.
type Manager struct {
	ctx  context.Context
	cfg  *config.Store
	log  *logger.Logger
	show func()
	hide func()
	quit func()
	emit func(string, interface{})
}

// Run starts the system tray (blocking). Call this in a goroutine.
func Run(ctx context.Context, cfg *config.Store, log *logger.Logger, show, hide, quit func(), emit ...func(string, interface{})) {
	var emitFn func(string, interface{})
	if len(emit) > 0 {
		emitFn = emit[0]
	}
	m := &Manager{ctx: ctx, cfg: cfg, log: log, show: show, hide: hide, quit: quit, emit: emitFn}
	systray.Run(m.onReady, m.onExit)
}

func (m *Manager) onReady() {
	systray.SetIcon(iconActive)
	systray.SetTitle("GitSync")

	mStatus := systray.AddMenuItem("GitSync — Initializing...", "Live synchronization status")
	mStatus.Disable()
	systray.AddSeparator()

	mOpen := systray.AddMenuItem("Open Dashboard", "Show the GitSync window")
	mPause := systray.AddMenuItemCheckbox(
		"Pause All Syncing",
		"Temporarily pause all automatic syncing",
		m.cfg.Config().Preferences.GlobalPause,
	)
	systray.AddSeparator()
	mQuit := systray.AddMenuItem("Quit GitSync", "Exit the application completely")

	readyMu.Lock()
	mStatusItem = mStatus
	mPauseItem = mPause
	isReady = true
	readyMu.Unlock()

	// Initial metrics push
	metricsMu.RLock()
	cur := lastMetrics
	metricsMu.RUnlock()
	cur.IsPaused = m.cfg.Config().Preferences.GlobalPause
	UpdateMetrics(cur)

	go m.menuLoop(mOpen, mPause, mQuit)
}

func (m *Manager) menuLoop(mOpen, mPause, mQuit *systray.MenuItem) {
	for {
		select {
		case <-mOpen.ClickedCh:
			m.show()

		case <-mPause.ClickedCh:
			m.toggleGlobalPause()

		case <-mQuit.ClickedCh:
			m.log.Info("tray", "quit requested from tray")
			systray.Quit()
			m.quit()
			return
		}
	}
}

