294: func (e *Engine) safePush(repo *config.RepoConfig) error {
295: 	dir := repo.LocalPath
296: 	branch := repo.Branch
297: 	if branch == "" {
298: 		branch = "main"
299: 	}
300: 
301: 	// 1. Initial push attempt
302: 	if _, err := e.exec.Run(dir, "push", "-u", "origin", branch); err == nil {
303: 		return nil
304: 	} else if isNetworkOrAuthError(err.Error()) {
305: 		// Network offline or authentication failures should not trigger rebase/conflict workflows
306: 		return err
307: 	}
308: 
309: 	if e.log != nil {
310: 		e.log.Warn("gitengine", "[%s] push rejected or remote divergence detected, attempting safe rebase", repo.RemoteName)
311: 	}
312: 
313: 	// 2. Fetch origin to update remote tracking refs
314: 	if _, err := e.exec.Run(dir, "fetch", "origin", branch); err != nil {
315: 		// If remote ref doesn't exist yet on origin, re-attempt push directly or return
316: 		if isRemoteRefNotFoundError(err.Error()) {
317: 			_, pushErr := e.exec.Run(dir, "push", "-u", "origin", branch)
318: 			return pushErr
319: 		}
320: 		return fmt.Errorf("fetch origin/%s: %w", branch, err)
321: 	}
322: 
323: 	// 3. Stash uncommitted work before rebasing
324: 	stashed := false
325: 	stashOut, _ := e.exec.Run(dir, "stash", "push", "-m", "gitsync-auto-stash")
326: 	if !strings.Contains(stashOut, "No local changes to save") && strings.TrimSpace(stashOut) != "" {
327: 		stashed = true
328: 	}
329: 
330: 	// 4. Attempt rebase onto fetched origin/<branch>
331: 	if _, err := e.exec.Run(dir, "pull", "--rebase", "origin", branch); err == nil {
332: 		// Rebase succeeded!
333: 		if stashed {
334: 			if _, popErr := e.exec.Run(dir, "stash", "pop"); popErr != nil && e.log != nil {
335: 				e.log.Warn("gitengine", "[%s] stash pop warning: %v", repo.RemoteName, popErr)
