418: func sanitizeBranchName(name string) string {
419: 	r := strings.NewReplacer(" ", "-", "\\", "-", ":", "-", "/", "-", "@", "-", "..", "-")
420: 	clean := r.Replace(name)
421: 	var sb strings.Builder
422: 	for _, ch := range clean {
423: 		if (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch == '-' || ch == '_' || ch == '.' {
424: 			sb.WriteRune(ch)
425: 		}
426: 	}
427: 	res := strings.Trim(sb.String(), "-.")
428: 	if res == "" {
429: 		return "host"
430: 	}
431: 	return res
432: }
