245: func (a *App) calculateTrayMetrics() tray.Metrics {
246: 	if a.cfg == nil || a.watchSvc == nil {
247: 		return tray.Metrics{}
248: 	}
249: 	cfg := a.cfg.Config()
250: 	statuses := a.watchSvc.Statuses()
251: 
252: 	m := tray.Metrics{
253: 		TotalRepos: len(cfg.Repos),
254: 		IsPaused:   cfg.Preferences.GlobalPause,
255: 	}
256: 
257: 	for _, r := range cfg.Repos {
258: 		if r.Enabled {
259: 			m.ActiveRepos++
260: 		}
261: 	}
262: 
263: 	for _, st := range statuses {
264: 		if st.State == "syncing" {
265: 			m.Syncing++
266: 		}
267: 		if st.State == "conflict" {
268: 			m.Conflicts++
269: 		}
270: 		if st.PendingFiles > 0 || st.State == "debouncing" {
271: 			m.PendingSyncs += st.PendingFiles
272: 			if st.PendingFiles == 0 {
273: 				m.PendingSyncs++
274: 			}
275: 		}
276: 	}
277: 
278: 	return m
279: }
