408: // runSync executes the sync workflow with mutual exclusion and the dirty/needsResync flag.
409: func (s *Service) runSync(repoID string) {
410: 	s.mu.RLock()
411: 	state, exists := s.states[repoID]
412: 	s.mu.RUnlock()
413: 	if !exists {
414: 		return
415: 	}
416: 
417: 	// Attempt to acquire per-repo execution lock
418: 	if !state.mu.TryLock() {
419: 		// Another sync is currently in progress: flag dirty so it immediately re-syncs when finished!
420: 		state.needsResync = true
421: 		s.log.Debug("watcher", "[%s] sync currently active; queued follow-up sync", repoID)
422: 		return
423: 	}
424: 	defer state.mu.Unlock()
425: 
426: 	// Loop as long as changes arrive while syncing (needsResync)
427: 	for {
428: 		state.needsResync = false
429: 
430: 		s.mu.Lock()
431: 		state.status.State = "syncing"
432: 		state.status.PendingFiles = 0
433: 		s.mu.Unlock()
434: 		s.emitStatuses()
435: 
436: 		repo := s.cfg.FindRepo(repoID)
437: 		if repo == nil {
438: 			return
439: 		}
440: 		account := s.cfg.FindAccount(repo.AccountID)
441: 
442: 		// File settling probe: brief pause to allow external file write handles to flush
443: 		time.Sleep(50 * time.Millisecond)
444: 
445: 		syncCtx, syncCancel := context.WithTimeout(context.Background(), 2*time.Minute)
446: 		err := s.git.Sync(syncCtx, repo, account, s.github)
447: 		syncCancel()
448: 
449: 		s.mu.Lock()
450: 		if err != nil {
451: 			errStr := err.Error()
452: 			if strings.Contains(errStr, "offline") || strings.Contains(errStr, "Could not resolve host") {
453: 				state.status.State = "offline"
454: 			} else if strings.Contains(errStr, "conflict") {
455: 				state.status.State = "conflict"
456: 				if s.emit != nil {
457: 					s.emit("toast:notify", map[string]interface{}{
458: 						"id":        fmt.Sprintf("conflict-%s-%d", repo.RemoteName, time.Now().UnixNano()),
459: 						"type":      "conflict",
460: 						"title":     "Git Conflict Isolated",
461: 						"message":   fmt.Sprintf("[%s] Changes safely preserved in conflict branch", repo.RemoteName),
462: 						"repoName":  repo.RemoteName,
463: 						"timestamp": time.Now().UTC().Format(time.RFC3339),
464: 					})
465: 				}
466: 			} else {
467: 				state.status.State = "error"
468: 			}
469: 			state.status.LastError = errStr
470: 			s.log.Error("sync", "[%s] sync failed: %v", repo.RemoteName, err)
471: 		} else {
472: 			state.status.State = "idle"
473: 			state.status.LastSyncAt = time.Now()
474: 			state.status.LastError = ""
475: 			s.log.Info("sync", "[%s] synced successfully", repo.RemoteName)
476: 			if s.emit != nil {
477: 				s.emit("toast:notify", map[string]interface{}{
478: 					"id":        fmt.Sprintf("sync-%s-%d", repo.RemoteName, time.Now().UnixNano()),
479: 					"type":      "success",
