481: 					"message":   fmt.Sprintf("[%s] Synced successfully to GitHub", repo.RemoteName),
482: 					"repoName":  repo.RemoteName,
483: 					"timestamp": time.Now().UTC().Format(time.RFC3339),
484: 				})
485: 			}
