	home, _ := os.UserHomeDir()
	backupDir := filepath.Join(home, ".gitsync", "backups", repoName)

	repo := config.RepoConfig{
		ID:         uuid.New().String(),
		LocalPath:  filepath.Clean(localPath),
		RemoteName: repoName,
		AccountID:  accountID,
		Visibility: visibility,
		Enabled:    true,
		Branch:     "main",
		CommitMsg:  "chore: auto-sync {{timestamp}}",
		BackupDir:  backupDir,
		CreatedAt:  time.Now(),
	}

	if err := a.cfg.AddRepo(repo); err != nil {
		return err
	}

	// Register with watcher service
	a.watchSvc.AddRepo(&repo)
	a.log.Info("app", "added repository: %s → %s", localPath, repoName)
