299: // safePush pushes to origin, falling back to fetch → rebase on divergence.
300: // If a merge conflict occurs, changes are safely isolated into a dedicated conflict
301: // branch (conflict/<hostname>/<timestamp>) and the working branch is reset to origin.
302: func (e *Engine) safePush(repo *config.RepoConfig) error {
303: 	dir := repo.LocalPath
304: 	branch := repo.Branch
305: 	if branch == "" {
306: 		branch = "main"
307: 	}
308: 
309: 	// 1. Initial push attempt
310: 	if _, err := e.exec.Run(dir, "push", "-u", "origin", branch); err == nil {
311: 		return nil
312: 	} else if isNetworkOrAuthError(err.Error()) {
313: 		// Network offline or authentication failures should not trigger rebase/conflict workflows
314: 		return err
315: 	}
316: 
317: 	if e.log != nil {
318: 		e.log.Warn("gitengine", "[%s] push rejected or remote divergence detected, attempting safe rebase", repo.RemoteName)
319: 	}
320: 
321: 	// 2. Fetch origin to update remote tracking refs
322: 	if _, err := e.exec.Run(dir, "fetch", "origin", branch); err != nil {
323: 		// If remote ref doesn't exist yet on origin, re-attempt push directly or return
324: 		if isRemoteRefNotFoundError(err.Error()) {
325: 			_, pushErr := e.exec.Run(dir, "push", "-u", "origin", branch)
326: 			return pushErr
327: 		}
328: 		return fmt.Errorf("fetch origin/%s: %w", branch, err)
329: 	}
330: 
331: 	// 3. Stash uncommitted work before rebasing
332: 	stashed := false
333: 	stashOut, _ := e.exec.Run(dir, "stash", "push", "-m", "gitsync-auto-stash")
334: 	if !strings.Contains(stashOut, "No local changes to save") && strings.TrimSpace(stashOut) != "" {
335: 		stashed = true
336: 	}
337: 
338: 	// 4. Attempt rebase onto fetched origin/<branch>
339: 	if _, err := e.exec.Run(dir, "pull", "--rebase", "origin", branch); err == nil {
340: 		// Rebase succeeded!
341: 		if stashed {
342: 			if _, popErr := e.exec.Run(dir, "stash", "pop"); popErr != nil && e.log != nil {
343: 				e.log.Warn("gitengine", "[%s] stash pop warning: %v", repo.RemoteName, popErr)
344: 			}
345: 		}
346: 		// Push rebased branch
347: 		if _, pushErr := e.exec.Run(dir, "push", "-u", "origin", branch); pushErr != nil {
348: 			return fmt.Errorf("push after rebase failed for [%s]: %w", repo.RemoteName, pushErr)
349: 		}
350: 		return nil
351: 	}
352: 
353: 	// 5. Merge conflict occurred during rebase: execute safe conflict isolation
354: 	if e.log != nil {
355: 		e.log.Warn("gitengine", "[%s] merge conflict encountered during pull --rebase, starting conflict isolation", repo.RemoteName)
356: 	}
357: 
358: 	// Abort the in-flight rebase to restore local commit state
359: 	_, _ = e.exec.Run(dir, "rebase", "--abort")
360: 
361: 	// Construct conflict branch name: conflict/<hostname>/<timestamp>
362: 	hostname, _ := os.Hostname()
363: 	if hostname == "" {
364: 		hostname = "host"
365: 	}
366: 	hostname = sanitizeBranchName(hostname)
367: 	stamp := time.Now().Format("20060102-150405")
368: 	conflictBranch := fmt.Sprintf("conflict/%s/%s", hostname, stamp)
369: 
370: 	// Create and switch to the conflict branch with the local commits
371: 	if _, err := e.exec.Run(dir, "checkout", "-b", conflictBranch); err != nil {
372: 		if e.log != nil {
373: 			e.log.Error("gitengine", "[%s] failed to create conflict branch %s: %v", repo.RemoteName, conflictBranch, err)
374: 		}
375: 	}
376: 
377: 	// If stashed work existed, pop and commit onto the conflict branch so nothing is lost
378: 	if stashed {
379: 		if _, err := e.exec.Run(dir, "stash", "pop"); err == nil {
380: 			if e.exec.HasUncommittedChanges(dir) {
381: 				_, _ = e.exec.Run(dir, "add", "--all")
382: 				_, _ = e.exec.Run(dir, "commit", "-m", fmt.Sprintf("chore: preserve uncommitted changes during conflict isolation %s", stamp))
383: 			}
384: 		}
385: 	}
386: 
387: 	// Try to push conflict branch to origin to preserve work remotely
388: 	if _, err := e.exec.Run(dir, "push", "-u", "origin", conflictBranch); err != nil {
389: 		if e.log != nil {
390: 			e.log.Warn("gitengine", "[%s] could not push conflict branch %s to origin: %v", repo.RemoteName, conflictBranch, err)
391: 		}
392: 	} else if e.log != nil {
393: 		e.log.Info("gitengine", "[%s] pushed conflict branch %s to origin", repo.RemoteName, conflictBranch)
394: 	}
395: 
396: 	// Switch back to primary branch
397: 	if _, err := e.exec.Run(dir, "checkout", branch); err != nil && e.log != nil {
398: 		e.log.Error("gitengine", "[%s] failed to switch back to %s: %v", repo.RemoteName, branch, err)
399: 	}
400: 
401: 	// Hard reset primary branch to origin/<branch> to restore clean sync state
402: 	if _, err := e.exec.Run(dir, "reset", "--hard", "origin/"+branch); err != nil && e.log != nil {
403: 		e.log.Error("gitengine", "[%s] failed to reset %s to origin/%s: %v", repo.RemoteName, branch, branch, err)
404: 	}
405: 
406: 	if e.log != nil {
407: 		e.log.Warn(
408: 			"gitengine",
409: 			"[%s] merge conflict detected; changes safely isolated to branch '%s', local %s reset to origin",
410: 			repo.RemoteName, conflictBranch, branch,
411: 		)
412: 	}
413: 
414: 	return fmt.Errorf("conflict detected in [%s]: local commits safely isolated to branch %q, %s reset to origin",
415: 		repo.RemoteName, conflictBranch, branch)
416: }
