418: func buildCommitMsg(template string, branchAndStatus ...string) string {
419: 	branch := "main"
420: 	porcelain := ""
421: 	if len(branchAndStatus) > 0 && strings.TrimSpace(branchAndStatus[0]) != "" {
422: 		branch = strings.TrimSpace(branchAndStatus[0])
423: 	}
424: 	if len(branchAndStatus) > 1 {
425: 		porcelain = branchAndStatus[1]
426: 	}
427: 
428: 	filesSummary := summarizeChangedFiles(porcelain)
429: 	ts := time.Now().Format("2006-01-02 15:04:05")
430: 
431: 	trimmed := strings.TrimSpace(template)
432: 	if trimmed == "" {
433: 		trimmed = "chore: auto-sync {{timestamp}}"
434: 	}
435: 	if strings.EqualFold(trimmed, "smart") || strings.EqualFold(trimmed, "{{smart}}") {
436: 		if filesSummary != "" {
437: 			return fmt.Sprintf("sync(%s): update %s", branch, filesSummary)
438: 		}
439: 		return fmt.Sprintf("sync(%s): auto-sync %s", branch, ts)
440: 	}
441: 
442: 	res := strings.ReplaceAll(trimmed, "{{timestamp}}", ts)
443: 	res = strings.ReplaceAll(res, "{{branch}}", branch)
444: 	if filesSummary == "" {
445: 		filesSummary = "files"
446: 	}
447: 	res = strings.ReplaceAll(res, "{{files}}", filesSummary)
448: 	return res
449: }
