451: func summarizeChangedFiles(porcelain string) string {
452: 	if strings.TrimSpace(porcelain) == "" {
453: 		return ""
454: 	}
455: 	var names []string
456: 	seen := make(map[string]bool)
457: 	for _, line := range strings.Split(strings.TrimSpace(porcelain), "\n") {
458: 		line = strings.TrimSpace(line)
459: 		if len(line) < 3 {
460: 			continue
461: 		}
462: 		pathPart := strings.TrimSpace(line[2:])
463: 		if idx := strings.Index(pathPart, " -> "); idx != -1 {
464: 			pathPart = strings.TrimSpace(pathPart[idx+4:])
465: 		}
466: 		pathPart = strings.Trim(pathPart, `"`)
467: 		base := filepath.Base(pathPart)
468: 		if base != "" && base != "." && !seen[base] {
469: 			seen[base] = true
470: 			names = append(names, base)
471: 		}
472: 	}
473: 	if len(names) == 0 {
474: 		return ""
475: 	}
476: 	if len(names) <= 2 {
477: 		return strings.Join(names, ", ")
478: 	}
479: 	return fmt.Sprintf("%s, %s (+%d more)", names[0], names[1], len(names)-2)
480: }
