482: func sanitizeBranchName(name string) string {
483: 	r := strings.NewReplacer(" ", "-", "\\", "-", ":", "-", "/", "-", "@", "-", "..", "-")
484: 	clean := r.Replace(name)
485: 	var sb strings.Builder
486: 	for _, ch := range clean {
487: 		if (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch == '-' || ch == '_' || ch == '.' {
488: 			sb.WriteRune(ch)
489: 		}
490: 	}
491: 	res := strings.Trim(sb.String(), "-.")
492: 	if res == "" {
493: 		return "host"
494: 	}
495: 	return res
496: }
