		}{Token: token, Error: resErr}
		close(outChan)

		// Gracefully close server in background
		go func() {
			shutdownCtx, sCancel := context.WithTimeout(context.Background(), 2*time.Second)
			defer sCancel()
			_ = server.Shutdown(shutdownCtx)
		}()
