import { useState } from 'react';
import { RepoCard } from './RepoCard';
import { PlusIcon, RepoIcon } from './Icons';
import type { RepoStatus, AppConfig } from '../types';

interface Props {
  statuses: RepoStatus[];
  config: AppConfig | null;
  globalPause: boolean;
  onTogglePause: () => void;
  onSyncNow: (repoId: string) => Promise<void>;
  onToggleRepo: (repoId: string, enabled: boolean) => Promise<void>;
  onRemoveRepo: (repoId: string) => Promise<void>;
  onAddRepo: () => void;
}

export function Dashboard({
  statuses,
  config,
  globalPause,
  onTogglePause,
  onSyncNow,
  onToggleRepo,
  onRemoveRepo,
  onAddRepo,
}: Props) {
  const [filter, setFilter] = useState<'all' | 'error' | 'syncing'>('all');

  const accounts = config?.accounts ?? [];
  const findAccount = (accountId: string) => accounts.find(a => a.id === accountId);
  const repoConfigs = config?.repos ?? [];

  const filteredStatuses = statuses.filter(s => {
    if (filter === 'error') return s.state === 'error' || s.state === 'conflict';
    if (filter === 'syncing') return s.state === 'syncing' || s.state === 'debouncing';
    return true;
  });

  const stats = {
    total: statuses.length,
    syncing: statuses.filter(s => s.state === 'syncing' || s.state === 'debouncing').length,
    errors: statuses.filter(s => s.state === 'error' || s.state === 'conflict').length,
    idle: statuses.filter(s => s.state === 'idle').length,
  };

  return (
    <div className="flex flex-col h-full overflow-hidden bg-[#0d1116]">
      {/* Header telemetry / actions bar */}
      <div className="flex items-center gap-4 px-4 py-2.5 border-b border-border bg-[#161b22] shrink-0">
        <div className="flex items-center gap-3 text-xs">
          <StatBadge label="Repositories" value={stats.total} color="text-[#e6edf3]" />
          <StatBadge label="Syncing" value={stats.syncing} color="text-[#2f81f7]" />
          <StatBadge label="Errors" value={stats.errors} color="text-[#f85149]" />
          <StatBadge label="Up to date" value={stats.idle} color="text-[#3fb950]" />
        </div>

        <div className="flex-1" />

        {/* Filter tabs */}
        <div className="flex items-center gap-1 bg-[#0d1116] p-0.5 rounded-md border border-border" data-wails-no-drag="">
          {(['all', 'syncing', 'error'] as const).map(f => (
            <button
              key={f}
              id={`filter-${f}`}
              onClick={() => setFilter(f)}
              className={`px-2 py-0.5 rounded text-[11px] font-medium transition-colors ${
                filter === f
                  ? 'bg-[#21262d] text-[#e6edf3] shadow-sm'
                  : 'text-[#8b949e] hover:text-[#e6edf3]'
              }`}
            >
              {f === 'all' ? 'All' : f === 'syncing' ? 'Active' : 'Errors'}
            </button>
          ))}
        </div>

        {/* Add repository button */}
        <button
          id="btn-add-repo"
          onClick={onAddRepo}
          data-wails-no-drag=""
          className="btn-primary flex items-center gap-1.5"
        >
          <PlusIcon className="w-3.5 h-3.5" />
          <span>Add Folder</span>
        </button>
      </div>

      {/* Global pause alert banner */}
      {globalPause && (
        <div className="flex items-center justify-between px-4 py-1.5 bg-[#d29922]/10 border-b border-[#d29922]/20 text-xs">
          <span className="text-[#d29922] font-medium">Automatic syncing is paused globally</span>
          <button
            onClick={onTogglePause}
            data-wails-no-drag=""
            className="text-xs text-[#d29922] hover:underline"
          >
            Resume Syncing
          </button>
        </div>
      )}

      {/* Repository grid */}
      <div className="flex-1 overflow-y-auto p-4">
        {filteredStatuses.length === 0 ? (
          <EmptyState onAddRepo={onAddRepo} hasRepos={statuses.length > 0} />
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
            {filteredStatuses.map(status => {
              const repoConf = repoConfigs.find(r => r.id === status.repo_id);
              const account = repoConf ? findAccount(repoConf.account_id) : undefined;
              return (
                <RepoCard
                  key={status.repo_id}
                  repo={status}
                  repoConfig={repoConf}
                  account={account}
                  onSyncNow={onSyncNow}
                  onToggle={onToggleRepo}
                  onRemove={onRemoveRepo}
                />
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

