658: function FormattedReleaseNotes({ notes }: { notes: string }) {
659:   // Parse **Full Changelog**: and strip redundant raw URLs since the banner already provides "Release Notes ↗"
660:   const cleaned = notes
661:     .replace(/\*\*Full Changelog\*\*:?\s*https?:\/\/[^\s)]+/gi, '')
662:     .replace(/https?:\/\/[^\s)]+/g, '')
663:     .trim();
664: 
665:   if (!cleaned) return null;
666: 
667:   const tokenRegex = /(\*\*[^*]+\*\*)/g;
668:   const parts = cleaned.split(tokenRegex);
669: 
670:   return (
671:     <span className="inline-flex flex-wrap items-center gap-x-1 gap-y-0.5">
672:       {parts.map((part, idx) => {
673:         if (!part) return null;
674:         if (part.startsWith('**') && part.endsWith('**')) {
675:           return (
676:             <strong key={idx} className="text-[#e6edf3] font-semibold">
677:               {part.slice(2, -2)}
678:             </strong>
679:           );
680:         }
681:         return <span key={idx}>{part}</span>;
682:       })}
683:     </span>
684:   );
685: }
