1225: 	if err := gitengine.InstallPortableGit(progressCb); err != nil {
1226: 		if a.log != nil {
1227: 			a.log.Error("installer", "Failed to install portable Git: %v", err)
1228: 		}
1229: 		return err
1230: 	}
1231: 
1232: 	// Update git engine with the newly configured portable Git path
1233: 	gitPath := ""
1234: 	if a.cfg != nil {
1235: 		gitPath = a.cfg.Config().Preferences.GitPath
1236: 	}
1237: 	if gitPath == "" {
1238: 		if targetExe, err := gitengine.GetPortableGitBinary(); err == nil {
1239: 			gitPath = targetExe
1240: 		}
1241: 	}
1242: 
1243: 	a.git = gitengine.New(a.log, gitPath)
1244: 	a.git.SetConfigStore(a.cfg)
1245: 	if a.watchSvc != nil {
1246: 		a.watchSvc.SetGitEngine(a.git)
1247: 	}
1248: 
1249: 	if a.cfg != nil {
1250: 		prefs := a.cfg.Config().Preferences
1251: 		prefs.GitPath = gitPath
1252: 		_ = a.cfg.UpdatePreferences(prefs)
1253: 		a.emitEvent("config:updated", a.cfg.Config())
1254: 	}
1255: 
1256: 	a.emitEvent("app:ready", map[string]interface{}{
1257: 		"gitAvailable": a.git.Available(),
1258: 		"gitPath":      a.git.GitPath(),
1259: 		"version":      "1.0.0",
1260: 		"timestamp":    time.Now().UTC().Format(time.RFC3339),
1261: 	})
1262: 
1263: 	if a.log != nil {
1264: 		a.log.Info("installer", "Portable Git successfully configured at: %s", a.git.GitPath())
1265: 	}
1266: 
1267: 	return nil
1268: }
