1292: // InstallUpdate downloads the latest release binary, stages it, spawns the replacement script,
1293: // and exits the application cleanly so the updated executable can launch.
1294: func (a *App) InstallUpdate() error {
1295: 	if a.updater == nil {
1296: 		return fmt.Errorf("updater service unavailable")
1297: 	}
1298: 	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Minute)
1299: 	defer cancel()
1300: 
1301: 	err := a.updater.InstallUpdate(ctx, func(pct int, status string) {
1302: 		if a.log != nil {
1303: 			a.log.Info("updater", "[%d%%] %s", pct, status)
1304: 		}
1305: 	})
1306: 	if err != nil {
1307: 		if a.log != nil {
1308: 			a.log.Error("updater", "install update failed: %v", err)
1309: 		}
1310: 		return err
1311: 	}
1312: 
1313: 	// Schedule clean application termination so the background script can overwrite the binary
1314: 	go func() {
1315: 		time.Sleep(300 * time.Millisecond)
1316: 		a.QuitApp()
1317: 	}()
1318: 	return nil
1319: }
