1429: func (a *App) InspectLocalFolder(localPath string) map[string]interface{} {
1430: 	raw := strings.TrimSpace(localPath)
1431: 	if raw == "" {
1432: 		return map[string]interface{}{
1433: 			"exists":   false,
1434: 			"isDir":    false,
1435: 			"hasGit":   false,
1436: 			"baseName": "",
1437: 		}
1438: 	}
1439: 	cleaned := filepath.Clean(raw)
1440: 	baseName := filepath.Base(cleaned)
1441: 	info, err := os.Stat(cleaned)
1442: 	if err != nil {
1443: 		return map[string]interface{}{
1444: 			"exists":   false,
1445: 			"isDir":    false,
1446: 			"hasGit":   false,
1447: 			"baseName": baseName,
1448: 		}
1449: 	}
1450: 	isDir := info.IsDir()
1451: 	hasGit := false
1452: 	if isDir {
1453: 		gitPath := filepath.Join(cleaned, ".git")
1454: 		if _, gErr := os.Stat(gitPath); gErr == nil {
1455: 			hasGit = true
1456: 		}
1457: 	}
1458: 	return map[string]interface{}{
1459: 		"exists":   true,
1460: 		"isDir":    isDir,
1461: 		"hasGit":   hasGit,
