1480: // cleanupStaleIndexLocks checks all watched repositories for leftover .git/index.lock files
1481: // from system crashes or forced process kills, removing them safely on startup.
1482: func (a *App) cleanupStaleIndexLocks() {
1483: 	cfg := a.cfg.Config()
1484: 	for _, r := range cfg.Repos {
1485: 		lockPath := filepath.Join(r.LocalPath, ".git", "index.lock")
1486: 		if info, err := os.Stat(lockPath); err == nil {
1487: 			// If file exists and was modified more than 5 seconds ago, it is a dead lock
1488: 			if time.Since(info.ModTime()) > 5*time.Second {
1489: 				if remErr := os.Remove(lockPath); remErr == nil {
1490: 					if a.log != nil {
1491: 						a.log.Warn("app", "[%s] removed stale .git/index.lock from previous crash", r.RemoteName)
1492: 					}
1493: 				}
1494: 			}
1495: 		}
1496: 	}
1497: }
1498: 
1499: // isSafePath prevents users from accidentally registering drive roots or critical OS directories.
1500: func isSafePath(path string) bool {
1501: 	abs, err := filepath.Abs(strings.TrimSpace(path))
1502: 	if err != nil {
1503: 		return false
1504: 	}
1505: 	abs = filepath.Clean(abs)
1506: 
1507: 	// Reject filesystem / drive roots (e.g. "C:\", "X:\", "/")
1508: 	parts := 0
1509: 	for p := abs; p != filepath.Dir(p); p = filepath.Dir(p) {
1510: 		parts++
1511: 	}
1512: 	if parts < 1 {
1513: 		return false
1514: 	}
1515: 
1516: 	// Reject the user's home directory root itself
1517: 	if home, err := os.UserHomeDir(); err == nil && home != "" {
1518: 		if strings.EqualFold(abs, filepath.Clean(home)) {
1519: 			return false
1520: 		}
1521: 	}
1522: 
1523: 	// Reject critical top-level OS / system directories
1524: 	norm := strings.ToLower(filepath.ToSlash(abs))
1525: 	if len(norm) >= 3 && norm[1] == ':' && norm[2] == '/' {
1526: 		rel := norm[3:]
1527: 		switch rel {
1528: 		case "windows", "program files", "program files (x86)", "programdata",
1529: 			"users", "$recycle.bin", "system volume information", "recovery":
1530: 			return false
1531: 		}
1532: 	} else {
1533: 		switch norm {
1534: 		case "/bin", "/sbin", "/usr", "/etc", "/var", "/proc", "/sys", "/dev",
1535: 			"/system", "/library", "/users", "/home", "/root":
1536: 			return false
1537: 		}
1538: 	}
1539: 
1540: 	return true
1541: }

