154: func (h *OAuthHandler) buildAuthURLLocked(state string) string {
155: 	authEndpoint := h.authURL
156: 	clientID := h.clientID
157: 	redirectURI := h.redirectURI
158: 	scopes := h.scopes
159: 
160: 	u, err := url.Parse(authEndpoint)
161: 	if err != nil {
162: 		return authEndpoint
163: 	}
164: 
165: 	q := u.Query()
166: 	q.Set("client_id", clientID)
167: 	q.Set("redirect_uri", redirectURI)
168: 	q.Set("scope", scopes)
169: 	q.Set("state", state)
170: 	u.RawQuery = q.Encode()
171: 
172: 	return u.String()
173: }
