175: // GenerateStateToken creates a cryptographically secure random string for anti-CSRF protection.
176: func GenerateStateToken() (string, error) {
177: 	b := make([]byte, 24)
178: 	if _, err := rand.Read(b); err != nil {
179: 		return "", fmt.Errorf("failed to generate random state token: %w", err)
180: 	}
181: 	return hex.EncodeToString(b), nil
