184: // ExchangeCode exchanges a temporary OAuth authorization code for a GitHub personal/user access token.
185: func (h *OAuthHandler) ExchangeCode(ctx context.Context, code string) (string, error) {
186: 	h.mu.Lock()
187: 	tokenEndpoint := h.tokenURL
188: 	clientID := h.clientID
189: 	clientSecret := h.clientSecret
190: 	redirectURI := h.redirectURI
191: 	h.mu.Unlock()
192: 
193: 	params := url.Values{}
194: 	params.Set("client_id", clientID)
195: 	params.Set("client_secret", clientSecret)
196: 	params.Set("code", code)
197: 	params.Set("redirect_uri", redirectURI)
198: 
199: 	req, err := http.NewRequestWithContext(ctx, http.MethodPost, tokenEndpoint, strings.NewReader(params.Encode()))
200: 	if err != nil {
201: 		return "", fmt.Errorf("create token exchange request: %w", err)
202: 	}
203: 
204: 	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
205: 	req.Header.Set("Accept", "application/json")
206: 
207: 	client := &http.Client{Timeout: 15 * time.Second}
208: 	resp, err := client.Do(req)
209: 	if err != nil {
210: 		return "", fmt.Errorf("execute token exchange: %w", err)
211: 	}
212: 	defer resp.Body.Close()
213: 
214: 	bodyBytes, err := io.ReadAll(resp.Body)
215: 	if err != nil {
216: 		return "", fmt.Errorf("read token exchange response: %w", err)
217: 	}
218: 
219: 	var tokenResp OAuthTokenResponse
220: 	if err := json.Unmarshal(bodyBytes, &tokenResp); err != nil {
221: 		return "", fmt.Errorf("decode token exchange JSON: %w (body: %s)", err, string(bodyBytes))
222: 	}
223: 
224: 	if tokenResp.Error != "" {
225: 		desc := tokenResp.ErrorDescription
226: 		if desc == "" {
227: 			desc = tokenResp.Error
228: 		}
229: 		return "", fmt.Errorf("GitHub OAuth error: %s", desc)
230: 	}
231: 
232: 	if strings.TrimSpace(tokenResp.AccessToken) == "" {
233: 		return "", fmt.Errorf("GitHub returned empty access token")
234: 	}
235: 
236: 	return tokenResp.AccessToken, nil
237: }
