239: // StartOAuthServer starts the local HTTP loopback server on the configured port,
240: // generates state, and returns the authorization URL alongside a result channel that emits the access token.
241: func (h *OAuthHandler) StartOAuthServer(parentCtx context.Context) (authURL string, resultChan <-chan struct {
242: 	Token string
