253: 		h.activeCancel()
254: 	}
255: 	if h.activeServer != nil {
256: 		_ = h.activeServer.Close()
257: 	}
258: 
259: 	serverCtx, serverCancel := context.WithCancel(parentCtx)
260: 	h.activeCancel = serverCancel
261: 
262: 	port := h.port
263: 	callbackPath := h.callbackPath
264: 	authURL = h.buildAuthURLLocked(state)
265: 	h.mu.Unlock()
266: 
267: 	addr := fmt.Sprintf("127.0.0.1:%d", port)
268: 	listener, err := net.Listen("tcp", addr)
269: 	if err != nil {
270: 		serverCancel()
271: 		return "", nil, fmt.Errorf("cannot bind OAuth loopback listener on %s (port may be in use): %w", addr, err)
272: 	}
273: 
274: 	outChan := make(chan struct {
275: 		Token string
276: 		Error error
277: 	}, 1)
278: 
279: 	mux := http.NewServeMux()
280: 	server := &http.Server{
281: 		Handler:      mux,
282: 		ReadTimeout:  10 * time.Second,
283: 		WriteTimeout: 10 * time.Second,
284: 	}
285: 
286: 	h.mu.Lock()
287: 	h.activeServer = server
288: 	h.mu.Unlock()
289: 
290: 	var once sync.Once
291: 	sendResult := func(token string, resErr error) {
292: 		once.Do(func() {
293: 			outChan <- struct {
294: 				Token string
295: 				Error error
296: 			}{Token: token, Error: resErr}
297: 			close(outChan)
298: 
299: 			// Keep server alive briefly so the browser's "Click here" focus fallback remains reachable,
300: 			// then shut down cleanly in the background.
301: 			go func() {
302: 				time.Sleep(15 * time.Second)
303: 				shutdownCtx, sCancel := context.WithTimeout(context.Background(), 2*time.Second)
304: 				defer sCancel()
305: 				_ = server.Shutdown(shutdownCtx)
306: 			}()
307: 		})
308: 	}
309: 
310: 	mux.HandleFunc("/auth/focus", func(w http.ResponseWriter, r *http.Request) {
311: 		h.mu.Lock()
312: 		focusFn := h.onFocus
313: 		h.mu.Unlock()
314: 		if focusFn != nil {
315: 			go focusFn()
316: 		}
317: 		w.WriteHeader(http.StatusNoContent)
318: 	})
