320: 	handleCallback := func(w http.ResponseWriter, r *http.Request) {
321: 		q := r.URL.Query()
322: 
323: 		// 1. Check for OAuth error returned by GitHub (e.g. user denied consent)
324: 		if errParam := q.Get("error"); errParam != "" {
325: 			errDesc := q.Get("error_description")
326: 			if errDesc == "" {
327: 				errDesc = errParam
328: 			}
329: 			w.Header().Set("Content-Type", "text/html; charset=utf-8")
330: 			w.WriteHeader(http.StatusBadRequest)
331: 			_, _ = w.Write([]byte(renderOAuthErrorHTML(errDesc)))
332: 			sendResult("", fmt.Errorf("GitHub authorization rejected: %s", errDesc))
