334: 		}
335: 
336: 		// 2. Validate anti-CSRF state token
337: 		receivedState := q.Get("state")
338: 		if receivedState == "" || receivedState != state {
339: 			w.Header().Set("Content-Type", "text/html; charset=utf-8")
340: 			w.WriteHeader(http.StatusBadRequest)
341: 			_, _ = w.Write([]byte(renderOAuthErrorHTML("Invalid security state token (possible CSRF attack). Please try again.")))
342: 			return
343: 		}
344: 
345: 		// 3. Extract temporary authorization code
346: 		code := strings.TrimSpace(q.Get("code"))
347: 		if code == "" {
348: 			w.Header().Set("Content-Type", "text/html; charset=utf-8")
349: 			w.WriteHeader(http.StatusBadRequest)
350: 			_, _ = w.Write([]byte(renderOAuthErrorHTML("No authorization code provided in callback.")))
351: 			return
352: 		}
353: 
354: 		// 4. Exchange code for access token
355: 		exchangeCtx, eCancel := context.WithTimeout(serverCtx, 15*time.Second)
356: 		defer eCancel()
357: 
358: 		accessToken, err := h.ExchangeCode(exchangeCtx, code)
359: 		if err != nil {
360: 			w.Header().Set("Content-Type", "text/html; charset=utf-8")
361: 			w.WriteHeader(http.StatusInternalServerError)
362: 			_, _ = w.Write([]byte(renderOAuthErrorHTML(fmt.Sprintf("Failed to exchange code: %v", err))))
363: 			sendResult("", fmt.Errorf("token exchange failed: %w", err))
364: 			return
365: 		}
366: 
367: 		// 5. Render beautiful success HTML page to the browser tab
368: 		w.Header().Set("Content-Type", "text/html; charset=utf-8")
369: 		w.WriteHeader(http.StatusOK)
370: 		_, _ = w.Write([]byte(renderOAuthSuccessHTML()))
371: 
372: 		sendResult(accessToken, nil)
373: 	}
374: 
375: 	mux.HandleFunc(callbackPath, handleCallback)
376: 	if callbackPath != "/auth/callback" {
377: 		mux.HandleFunc("/auth/callback", handleCallback)
378: 	}
379: 	if callbackPath != "/callback" {
380: 		mux.HandleFunc("/callback", handleCallback)
381: 	}
382: 
383: 	// Also catch root `/` redirect if needed
384: 	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
