670: func htmlEscape(s string) string {
671: 	s = strings.ReplaceAll(s, "&", "&amp;")
672: 	s = strings.ReplaceAll(s, "<", "&lt;")
673: 	s = strings.ReplaceAll(s, ">", "&gt;")
674: 	s = strings.ReplaceAll(s, "\"", "&quot;")
675: 	s = strings.ReplaceAll(s, "'", "&#39;")
676: 	return s
677: }

