203: // EncryptPAT encrypts a plaintext PAT for storage using AES-256-GCM with a random nonce.
204: func (s *Store) EncryptPAT(plaintext string) (string, error) {
205: 	block, err := aes.NewCipher(s.key)
206: 	if err != nil {
207: 		return "", fmt.Errorf("create cipher: %w", err)
208: 	}
209: 	gcm, err := cipher.NewGCM(block)
210: 	if err != nil {
211: 		return "", fmt.Errorf("create gcm: %w", err)
212: 	}
213: 	nonce := make([]byte, gcm.NonceSize())
214: 	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
215: 		return "", fmt.Errorf("read random nonce: %w", err)
216: 	}
217: 	ciphertext := gcm.Seal(nonce, nonce, []byte(plaintext), nil)
218: 	return base64.StdEncoding.EncodeToString(ciphertext), nil
219: }
