221: // DecryptPAT decrypts a stored encrypted PAT using AES-256-GCM.
222: func (s *Store) DecryptPAT(encrypted string) (string, error) {
223: 	data, err := base64.StdEncoding.DecodeString(encrypted)
224: 	if err != nil {
225: 		return "", fmt.Errorf("base64 decode: %w", err)
226: 	}
227: 	block, err := aes.NewCipher(s.key)
228: 	if err != nil {
229: 		return "", fmt.Errorf("create cipher: %w", err)
230: 	}
231: 	gcm, err := cipher.NewGCM(block)
232: 	if err != nil {
233: 		return "", fmt.Errorf("create gcm: %w", err)
234: 	}
235: 	nonceSize := gcm.NonceSize()
236: 	if len(data) < nonceSize {
237: 		return "", fmt.Errorf("ciphertext too short: length %d, min %d", len(data), nonceSize)
238: 	}
239: 	nonce, ciphertext := data[:nonceSize], data[nonceSize:]
240: 	plaintext, err := gcm.Open(nil, nonce, ciphertext, nil)
241: 	if err != nil {
242: 		return "", fmt.Errorf("gcm decrypt failed: %w", err)
243: 	}
244: 	return string(plaintext), nil
245: }
