254: func (s *Store) saveLocked() error {
255: 	data, err := json.MarshalIndent(s.config, "", "  ")
256: 	if err != nil {
257: 		return fmt.Errorf("marshal config: %w", err)
258: 	}
259: 
260: 	tmpPath := s.path + fmt.Sprintf(".tmp-%d", time.Now().UnixNano())
261: 	if err := os.WriteFile(tmpPath, data, 0600); err != nil {
262: 		return fmt.Errorf("write tmp config: %w", err)
263: 	}
264: 
265: 	// Windows-safe atomic replace:
266: 	// If destination exists, remove first on Windows, then rename.
267: 	_ = os.Remove(s.path)
268: 	if err := os.Rename(tmpPath, s.path); err != nil {
269: 		// Fallback: write directly if rename fails
270: 		_ = os.Remove(tmpPath)
271: 		return os.WriteFile(s.path, data, 0600)
272: 	}
273: 	return nil
274: }
