292: // deriveKey creates a deterministic 32-byte key from hardware and OS identifiers.
293: func deriveKey() []byte {
294: 	platformID := getPlatformMachineID()
295: 	hostname, _ := os.Hostname()
296: 	homeDir, _ := os.UserHomeDir()
297: 	username := os.Getenv("USERNAME")
298: 	if username == "" {
299: 		username = os.Getenv("USER")
300: 	}
301: 
302: 	seed := fmt.Sprintf("%s|%s|%s|%s|%s|%s|gitsync-salt-v2",
303: 		platformID, hostname, homeDir, username, runtime.GOOS, runtime.GOARCH)
304: 
305: 	hash := sha256.Sum256([]byte(seed))
306: 	return hash[:]
307: }
