// RemoveAccount deletes a GitHub account and purges cached clients.
func (a *App) RemoveAccount(accountID string) error {
	a.github.InvalidateClient(accountID)
	// Also clean up any remote-only (unlinked) repository entries belonging to this account
	if a.cfg != nil {
		repos := a.cfg.Config().Repos
		for _, r := range repos {
			if r.AccountID == accountID && strings.TrimSpace(r.LocalPath) == "" {
				if a.watchSvc != nil {
					a.watchSvc.RemoveRepo(r.ID)
				}
				_ = a.cfg.RemoveRepo(r.ID)
			}
		}
	}
	if err := a.cfg.RemoveAccount(accountID); err != nil {
		return err
	}
	a.emitEvent("config:updated", a.cfg.Config())
	a.log.Info("app", "removed account: %s", accountID)
	return nil
}

