// Config returns a pointer to the live AppConfig under read lock.
func (s *Store) Config() *AppConfig {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.config
}

args.Target:
// Config returns a safe copy of the current AppConfig under read lock so callers
// can iterate over Accounts and Repos without racing with slice mutations.
func (s *Store) Config() *AppConfig {
	s.mu.RLock()
	defer s.mu.RUnlock()
	if s.config == nil {
		return defaultConfig()
	}
	copied := *s.config
	copied.Accounts = make([]Account, len(s.config.Accounts))
	copy(copied.Accounts, s.config.Accounts)
	copied.Repos = make([]RepoConfig, len(s.config.Repos))
	copy(copied.Repos, s.config.Repos)
	return &copied
}

